/* Twelve explicit Year 11 electricity scenario journeys. Original exam-style practice; no fabricated exam attribution. */
(function(){'use strict';const C=window.PhysicsScenarioCourse,H=C.helpers;const{esc,math:E,note:N,steps:W,paper,reveal:R,svg,text:rawText,line,arrow,ball,number}=H;
const text=(x,y,s,color='#18374d',anchor='start')=>{const max=Math.max(18,Math.floor((735-x)/10));if(anchor!=='start'||s.length<=max)return rawText(x,y,s,color,anchor);const words=s.split(' '),rows=[];let row='';for(const word of words){if((row+' '+word).trim().length>max&&row){rows.push(row);row=word;}else row+=(row?' ':'')+word;}if(row)rows.push(row);return rows.map((r,i)=>rawText(x,y+i*24,r,color,anchor)).join('');};
const P=t=>'<p>'+t+'</p>';const rect=(x,y,w,h,label,fill='#e5f1f6')=>'<rect x="'+x+'" y="'+y+'" width="'+w+'" height="'+h+'" fill="'+fill+'" stroke="#18374d" stroke-width="2"/>'+text(x+w/2,y+h/2+7,label,'#18374d','middle');
const wire=(x,y,a,b)=>line(x,y,a,b,'#526d82');const node=(x,y)=>ball(x,y,5,'#18374d');
function res(x,y,w,label){return wire(x-35,y,x,y)+rect(x,y-16,w,32,'')+wire(x+w,y,x+w+35,y)+text(x+w/2,y-32,label,'#18374d','middle');}
function battery(x,y,label){return wire(x,y-65,x,y-18)+wire(x-23,y-18,x+23,y-18)+wire(x-12,y+10,x+12,y+10)+wire(x,y+10,x,y+65)+text(x-35,y-15,'+','#18374d','end')+text(x-35,y+20,'−','#18374d','end')+text(x+35,y+25,label);}
function circleMeter(x,y,label){return '<circle cx="'+x+'" cy="'+y+'" r="24" fill="#fff" stroke="#18374d" stroke-width="2"/>'+text(x,y+7,label,'#18374d','middle');}
function simple(kind='series',labels=['R₁','R₂'],supply='Vₛ'){
 let b=text(70,40,kind==='parallel'?'Two branches join the same nodes A and B':'One route: both resistors carry the same current')+battery(95,225,supply)+wire(95,160,95,115)+wire(95,290,95,355)+wire(95,355,680,355)+wire(680,355,680,115);
 if(kind==='parallel'){b+=wire(95,115,260,115)+wire(260,115,260,245)+wire(560,115,680,115)+wire(560,115,560,245)+wire(260,115,310,115)+res(310,115,200,labels[0])+wire(545,115,560,115)+wire(260,245,310,245)+res(310,245,200,labels[1])+wire(545,245,560,245)+node(260,115)+node(560,115)+text(240,90,'A')+text(580,90,'B')+arrow(185,115,230,115,'#0b8774')+arrow(275,190,305,190,'#2a6bb2')+text(290,330,'Same VAB; Iₜ = I₁ + I₂');}
 else{b+=wire(95,115,230,115)+res(230,115,120,labels[0])+wire(385,115,430,115)+res(430,115,120,labels[1])+wire(585,115,680,115)+arrow(355,355,270,355,'#0b8774')+text(275,320,'common conventional current I');}
 return svg(kind+' circuit with labelled ideal source and resistor connections',b+text(80,420,'Ideal source and wires. Symbols are schematic, not to scale.'),460);
}
function meters(){let b=text(70,40,'A measures current through the load; V compares its terminals')+battery(110,230,'source')+wire(110,165,110,100)+wire(110,295,110,355)+wire(110,100,300,100)+res(300,100,180,'load R')+wire(515,100,650,100)+wire(650,100,650,355)+wire(110,355,356,355)+circleMeter(380,355,'A')+wire(404,355,650,355)+wire(260,100,260,220)+wire(520,100,520,220)+wire(260,220,356,220)+circleMeter(380,220,'V')+wire(404,220,520,220)+node(260,100)+node(520,100)+text(130,410,'A: series, low resistance')+text(400,410,'V: parallel, high resistance');return svg('Ammeter correctly in series and voltmeter correctly across the load',b,460);}
function carriers(){return svg('Microscopic negative carrier drift and conventional current point in opposite directions',text(70,40,'Metal wire: mobile electrons; positive lattice stays in place')+rect(100,130,560,120,'')+[155,255,355,455,555].map(x=>ball(x,165,16,'#d2e4ed')+text(x,172,'+','#18374d','middle')+ball(x+30,215,9,'#2a6bb2')).join('')+arrow(150,95,600,95,'#0b8774')+text(250,75,'conventional current →','#0b8774')+arrow(600,300,150,300,'#2a6bb2')+text(250,340,'electron drift ←','#2a6bb2')+text(100,405,'Electron dots represent carriers; they are not moving positive ions.'),450);}
function junction(){return svg('Charge conservation at a junction with one incoming current and two outgoing currents',arrow(90,200,330,200,'#0b8774')+node(350,200)+wire(330,200,350,200)+arrow(350,200,600,95,'#2a6bb2')+arrow(350,200,600,300,'#c87518')+text(110,170,'Iₜ enters')+text(520,70,'I₁ leaves')+text(520,345,'I₂ leaves')+text(120,395,'Steady flow: Iₜ = I₁ + I₂; charge does not build up.'),440);}
function open(){return svg('Open-switch circuit: a gap prevents steady current although a voltage can span the switch',text(80,45,'OPEN SWITCH: the only route is broken')+battery(110,225,'Vₛ')+wire(110,160,110,110)+wire(110,290,110,340)+wire(110,340,650,340)+wire(650,340,650,110)+wire(110,110,285,110)+node(285,110)+wire(285,110,355,65)+node(370,110)+wire(370,110,435,110)+res(435,110,100,'load')+wire(570,110,650,110)+text(270,185,'gap: I = 0')+text(180,405,'With ideal wires and a single source, source V appears across the gap.'),450);}
function nodes(){return svg('Series node potentials: P is 12 volts, M is 8 volts, N is zero volts',text(80,40,'Choose the negative source terminal N as the 0 V reference')+battery(100,230,'12 V')+wire(100,165,100,110)+wire(100,295,100,355)+wire(100,355,650,355)+wire(650,355,650,110)+wire(100,110,225,110)+res(225,110,110,'4 V drop')+wire(370,110,425,110)+res(425,110,110,'8 V drop')+wire(570,110,650,110)+node(170,110)+node(390,110)+node(650,290)+text(170,70,'P: 12 V','#18374d','middle')+text(390,175,'M: 8 V','#18374d','middle')+text(520,290,'N: 0 V')+text(160,420,'Along current: 12 V → 8 V → 0 V. Drops sum to 12 V.'),465);}
function pulse(){return svg('Triangular current-time pulse rises to 0.600 amperes at 4 seconds and falls to zero at 6 seconds',arrow(100,330,690,330,'#0b8774')+arrow(100,330,100,65,'#2a6bb2')+'<path d="M100 330L460 100L640 330Z" fill="#def0e6" stroke="#c87518" stroke-width="4"/>'+text(120,45,'current I (A)')+text(460,80,'0.600 A','#18374d','middle')+text(100,365,'0','#18374d','middle')+text(460,365,'4.00','#18374d','middle')+text(640,365,'6.00','#18374d','middle')+text(530,410,'time t (s)')+text(175,265,'Charge Q = signed area'),450);}
function iv(){return svg('Ohmic graph convention: voltage on vertical axis and current on horizontal, straight gradient is resistance',arrow(110,330,675,330,'#0b8774')+arrow(110,330,110,65,'#2a6bb2')+line(110,330,610,90,'#c87518')+text(130,45,'V (V)')+text(580,400,'I (A)')+text(380,175,'gradient = ΔV/ΔI = R')+text(160,430,'If axes are swapped, gradient is 1/R. Constant-temperature model.'),465);}
function lampgraph(){let p='';for(let i=0;i<=60;i++){let f=i/60;p+=(i?'L':'M')+(110+530*f)+' '+(330-230*Math.pow(f,.48));}return svg('Filament lamp I versus V curve flattens as operating resistance increases',arrow(110,330,675,330,'#0b8774')+arrow(110,330,110,65,'#2a6bb2')+'<path d="'+p+'" fill="none" stroke="#c87518" stroke-width="4"/>'+text(130,45,'I (A)')+text(580,400,'V (V)')+text(250,250,'nonlinear characteristic')+text(155,430,'Schematic shape only: use supplied data for numerical readings.'),465);}
function diode(){return svg('Diode forward and reverse polarity with cathode bar and conventional current direction',text(80,45,'Forward current flows anode → cathode in the conducting model')+wire(100,200,315,200)+'<path d="M315 155L395 200L315 245Z" stroke="#18374d" stroke-width="3" fill="#dcebf3"/>'+wire(395,150,395,250)+wire(395,200,660,200)+text(195,290,'anode A')+text(410,290,'cathode K: bar')+arrow(145,125,575,125,'#0b8774')+text(170,360,'Forward: A at higher potential than K')+text(170,400,'Reverse: very small current below breakdown (model).'),450);}
function led(){return svg('Low-voltage LED and current-limiting resistor in series with labelled voltage drops',text(70,40,'One route: resistor + forward LED; the drops add')+battery(100,230,'Vₛ')+wire(100,165,100,125)+wire(100,295,100,350)+wire(100,350,670,350)+wire(670,350,670,125)+wire(100,125,230,125)+res(230,125,110,'R; drop Vᵣ')+wire(375,125,435,125)+'<path d="M435 95L490 125L435 155Z" fill="#dcebf3" stroke="#18374d" stroke-width="3"/>'+wire(490,90,490,160)+wire(490,125,670,125)+arrow(450,87,475,55,'#c87518')+arrow(475,87,500,55,'#c87518')+text(430,200,'LED: drop VLED')+text(180,285,'I = (Vₛ − VLED)/R')+text(180,410,'Forward-drop approximation supplied by the question; low-voltage theory.'),450);}
function verticalDivider(sensor=false,loaded=false){let b=text(60,35,sensor?'Output is junction relative to 0 V; sensor position matters':loaded?'A finite output load is parallel with the lower resistor':'Unloaded divider: Vout is across the lower resistor')+wire(260,80,260,105)+rect(240,105,40,75,'')+wire(260,180,260,235)+rect(240,235,40,75,'')+wire(260,310,260,365)+node(260,210)+text(130,80,'+Vₛ')+text(295,150,sensor?'fixed upper R':'upper R₁')+text(295,275,sensor?'lower NTC sensor':'lower R₂')+wire(260,210,590,210)+text(425,190,'Vout junction')+wire(260,365,590,365)+text(430,395,'0 V reference')+text(70,445,loaded?'Reduce lower resistor and load in parallel before applying the ratio.':'Vout = Vₛ Rbottom/(Rtop + Rbottom) when unloaded.');if(sensor)b+=line(225,325,295,225,'#c87518');if(loaded)b+=wire(560,210,560,245)+rect(540,245,40,65,'')+wire(560,310,560,365)+text(600,280,'load');return svg('Explicit divider junction and zero-volt output reference'+(loaded?' with output load':''),b,485);}
function wireGeometry(){return svg('Uniform wire resistance geometry with length and circular cross-sectional radius labelled',text(75,40,'EXTENSION: R = ρL/A at stated temperature')+'<path d="M180 160H575V260H180Z" fill="#dcebf3" stroke="#18374d" stroke-width="2"/><ellipse cx="180" cy="210" rx="30" ry="50" fill="#bdd8e5" stroke="#18374d" stroke-width="2"/><ellipse cx="575" cy="210" rx="30" ry="50" fill="none" stroke="#18374d" stroke-width="2"/>'+line(180,110,575,110)+text(375,85,'length L','#18374d','middle')+line(180,210,180,160,'#c87518')+text(80,210,'radius r')+text(200,330,'cross-sectional area A = πr²')+text(140,415,'ρ is a material property; R also depends on geometry.'),460);}
function leads(){return svg('Outgoing and return lead resistances both in series with the load',text(70,40,'Lead pair resistance includes both conductors')+battery(100,230,'12 V')+wire(100,165,100,110)+wire(100,295,100,355)+wire(100,110,270,110)+res(270,110,160,'outgoing lead')+wire(465,110,630,110)+wire(630,110,630,185)+rect(610,185,40,75,'')+wire(630,260,630,355)+wire(100,355,270,355)+res(270,355,160,'return lead')+wire(465,355,630,355)+text(655,225,'load')+text(160,435,'Vload = Vsource − I(Routgoing + Rreturn)'),480);}
function compound(){return svg('Compound topology: series resistor before a split into two parallel branches',text(65,35,'Reduce the two branches first, then add the series resistor')+battery(85,235,'12 V')+wire(85,170,85,100)+wire(85,300,85,365)+wire(85,365,695,365)+wire(695,365,695,100)+wire(85,100,180,100)+res(180,100,95,'2 Ω')+wire(310,100,350,100)+wire(350,100,350,235)+wire(610,100,695,100)+wire(610,100,610,235)+wire(350,100,400,100)+res(400,100,155,'6 Ω')+wire(590,100,610,100)+wire(350,235,400,235)+res(400,235,155,'3 Ω')+wire(590,235,610,235)+node(350,100)+node(610,100)+text(385,300,'parallel group: Vgroup = 6 V')+text(130,425,'Source current 3 A splits into 1 A and 2 A.'),465);}
function reduced(){return svg('Reduced compound circuit replaces parallel 6 and 3 ohm branches with 2 ohm equivalent',text(70,35,'Equivalent group preserves terminal voltage and total current')+battery(95,230,'12 V')+wire(95,165,95,110)+wire(95,295,95,355)+wire(95,355,680,355)+wire(680,355,680,110)+wire(95,110,215,110)+res(215,110,120,'series 2 Ω')+wire(370,110,440,110)+res(440,110,120,'group 2 Ω')+wire(595,110,680,110)+text(190,260,'Rtotal = 4 Ω; Itotal = 3 A')+text(135,420,'Restore group voltage before finding original branch currents.'),460);}
function ac(square=false){let p='';for(let i=0;i<=160;i++){let f=i/160,x=110+530*f,y=220-95*(square?(Math.sin(f*4*Math.PI)>=0?1:-1):Math.sin(f*4*Math.PI));p+=(i?'L':'M')+x+' '+y;}return svg(square?'Square voltage waveform with positive and negative levels':'Sinusoidal voltage waveform with signed peaks and two full periods',arrow(95,220,690,220,'#0b8774')+arrow(110,345,110,60,'#2a6bb2')+'<path d="'+p+'" fill="none" stroke="#c87518" stroke-width="4"/>'+text(120,45,'voltage v (V)')+text(75,130,'+Vp','#18374d','end')+text(75,320,'−Vp','#18374d','end')+text(550,380,'time t (s)')+text(120,420,square?'Square: v² is constant; Vrms = Vp (extension).':'Sine: full cycle has zero signed mean but nonzero heating (extension).'),460);}
function thermistor(){return svg('NTC resistance-temperature characteristic slopes downward, with explicitly labelled axes',arrow(110,335,690,335,'#0b8774')+arrow(110,335,110,55,'#2a6bb2')+'<path d="M140 90C230 200 370 265 650 300" fill="none" stroke="#c87518" stroke-width="4"/>'+text(130,35,'resistance R (Ω)')+text(435,395,'temperature T (°C)')+text(150,445,'NTC sensor application: schematic trend, not a numerical calibration.'),485);}
function safety(fault=false,rcd=false){let b=text(60,35,rcd?'RCD monitors both active and neutral; earth bypasses the sensor':fault?'Active-to-case fault: protective earth gives a fault return path':'Protection functions differ: fuse/breaker, earth and RCD')+rect(555,90,130,260,'')+text(660,315,'case')+wire(90,120,170,120)+rect(170,105,75,30,'F')+wire(245,120,555,120)+wire(90,230,555,230)+wire(90,335,555,335)+text(60,88,'active')+text(60,205,'neutral')+text(60,380,'protective earth')+node(555,335)+rect(605,140,40,60,'')+wire(555,120,625,120)+wire(625,120,625,140)+wire(625,200,625,230)+wire(555,230,625,230)+text(545,425,'normal load inside case','#18374d','end');
 if(rcd)b+='<rect x="310" y="80" width="85" height="200" fill="none" stroke="#a15bb5" stroke-width="3" stroke-dasharray="5 4"/>'+text(352,65,'RCD','#a15bb5','middle')+text(400,95,'Iout →')+text(400,265,'← Ireturn');
 if(fault)b+=line(490,120,555,335,'#c87518',true)+text(375,300,'fault to case','#a05910');
 b+=text(75,465,'Conceptual schematic only. Earth is not the normal neutral return.');return svg('Electrical protection schematic: fuse in active, active and neutral load route, separate protective earth to case'+(fault?' with active-to-case fault':rcd?' with RCD sensing both load conductors':''),b,505);}
function insulation(){return svg('Double-insulated conceptual appliance separates live parts from accessible exterior','<rect x="150" y="80" width="430" height="280" fill="#e4edf3" stroke="#18374d" stroke-width="3"/><rect x="205" y="135" width="320" height="170" fill="#fff" stroke="#2a6bb2" stroke-width="12"/>'+rect(275,185,175,70,'live component','#f1dfc4')+text(145,45,'Accessible exterior')+text(220,345,'protective insulation arrangements')+text(95,425,'Class II model does not rely on a case protective-earth connection.'),465);}
function powerbudget(){return svg('Power budget: electrical input divides into useful output and heating',text(85,40,'Power measures the rate of energy transfer')+rect(70,160,180,75,'100 W input')+arrow(250,198,405,130,'#0b8774')+arrow(250,198,405,290,'#c87518')+rect(415,85,250,80,'75 W useful output')+rect(415,250,250,80,'25 W heating')+text(125,400,'100 W = 75 W + 25 W; efficiency = 75/100 = 75%.'),450);}
function powergraph(){return svg('Power-time rectangle with 6 watt height and 30 second duration has 180 joule energy area',arrow(100,330,685,330,'#0b8774')+arrow(100,330,100,50,'#2a6bb2')+'<path d="M100 330V110H610V330Z" fill="#e5f2e8" stroke="#c87518" stroke-width="3"/>'+text(115,35,'power P (W)')+text(65,117,'6 W','#18374d','end')+text(610,365,'30 s','#18374d','middle')+text(260,235,'Energy = 6 × 30 = 180 J')+text(530,410,'time t (s)'),460);}
function rectified(){let p='';for(let i=0;i<=160;i++){let f=i/160;p+=(i?'L':'M')+(110+530*f)+' '+(320-200*Math.max(0,Math.sin(f*4*Math.PI)));}return svg('Half-wave rectified voltage pulses keep one sign and remain time-varying',arrow(95,320,690,320,'#0b8774')+arrow(110,340,110,50,'#2a6bb2')+'<path d="'+p+'" fill="none" stroke="#c87518" stroke-width="4"/>'+text(120,35,'voltage v (V)')+text(525,385,'time t (s)')+text(130,435,'Extension: one polarity blocked; pulses are not smooth steady DC.'),475);}
const F={powerbudget,powergraph,rectified,carriers,junction,loop:()=>simple('series',['load 1','load 2']),open,meters,pulse,nodes,parallel:()=>simple('parallel'),series:()=>simple(),iv,lampgraph,diode,led,divider:()=>verticalDivider(),sensor:()=>verticalDivider(true),loaded:()=>verticalDivider(false,true),thermistor,wire:wireGeometry,lead:leads,compound,reduced,ac:()=>ac(),square:()=>ac(true),safety:()=>safety(),fault:()=>safety(true),rcd:()=>safety(false,true),insulation};
const diagramsByParent={
 'charge-current-voltage':[['carriers','junction','pulse'],['meters','nodes','open'],['meters','pulse','junction']],
 'resistance-energy-power':[['iv','lampgraph','diode'],['powerbudget','powergraph','parallel'],['wire','lead','series']],
 'series-parallel-circuits':[['series','divider','nodes'],['parallel','junction','meters'],['compound','reduced','loaded']],
 'components-ac-safety':[['diode','led','sensor'],['ac','square','rectified'],['safety','fault','rcd']]};
function table(points){return '<table class="pf-marking"><thead><tr><th>Working and reasoning</th><th>Marks</th></tr></thead><tbody>'+points.map(p=>'<tr><td>'+esc(p)+'</td><td>1</td></tr>').join('')+'</tbody></table>';}
function build(d){const pages=[],add=(chapter,title,html,type='learn')=>pages.push({chapter,title,html:'<div class="pp-page">'+html+'</div>',type});const ds=diagramsByParent[d.parent.replace('y11-','')][Number(d.id.slice(-1))-1];
 d.concepts.forEach(([title,body,eq,fig],i)=>{if([0,7,12].includes(i))fig=ds[[0,7,12].indexOf(i)];add(i<8?0:1,title,(fig?F[fig](): '')+P(body)+(eq?E(eq):'')+(i===0&&d.extension?N('Extension boundary',d.extension):''));});
 d.examples.forEach((e,i)=>{add(2,e.title+': read and draw',(e.fig?F[e.fig]():F[ds[i+1]]())+N('Original exam-style worked scenario',e.q)+paper('Identify the givens and unknown for example '+(i+1)),'worked');add(2,e.title+': choose the model',P(e.plan)+N('Before calculating','Identify what is shared, what is fixed, and which measurement belongs to each component. State any supplied idealisation before using it.'),'worked');add(2,e.title+': explain every step',W(e.work),'worked');add(2,e.title+': check and interpret',P(e.check)+paper('Explain why the chosen relationship fits this scenario'),'worked');});
 d.guided.forEach((v,i)=>add(3,v.title,number(d.id+'-g'+i,v.q,v.value,v.unit,v.why,v.tol)+R('Explain the method',P(v.why)),'guided'));
 d.practice.forEach((v,i)=>add(3,'Independent scenario '+(i+1),N('Original exam-style question · '+v.points.length+' marks',v.q)+paper('Your independent reasoning and working '+(i+1))+R('Compare with explained marking points',table(v.points)),'practice'));
 add(3,'Choose the model in a changed scenario',P(d.subtitle)+P('Compare the two worked scenarios. Which quantity is fixed in each, and which equation would fail if that assumption changed? Explain using the relevant circuit nodes, carrier direction or waveform.')+paper('Compare the scenario conditions')+R('Review the relevant constraints',P(d.examples.map(e=>e.check).join(' '))));
 add(3,'Keep this reference',E(d.reference)+N('Solve deliberately','Sketch and label first; choose the local relationship; convert units; calculate with guard digits; check conservation and interpret the answer.')+(d.extension?N('Syllabus boundary',d.extension):''));
 const spec={id:d.id,parent:d.parent,title:d.title,shortTitle:d.shortTitle,subtitle:d.subtitle,pages,bank:d.bank,chapters:[['Recognise','Identify the physical situation and quantities'],['Build','Understand models, diagrams and relationships'],['Solve','Two original worked scenarios with explained decisions'],['Practise','Guided checks and independent transfer']],practice:d.practice,constants:'Use ideal sources, wires and meters where stated; e = 1.60 × 10⁻¹⁹ C. Convert to SI units unless a resistance ratio or kWh calculation explicitly uses compatible units. Extension content is labelled.',focus:{question:d.practice[0].q,points:d.practice[0].points,claim:'The same circuit equation can be used without checking the connections or operating conditions.'},summary:d.subtitle};if(pages.length<30||spec.bank.length<6)throw Error('Incomplete electricity lesson '+d.id);C.register(spec);
}

const DATA=[{"id":"y11-charge-current-voltage-focus-1","parent":"y11-charge-current-voltage","title":"Charge and current: carriers, direction and junctions","shortTitle":"Charge and current","subtitle":"Explain what moves, then calculate charge flow through a wire or branching circuit.","concepts":[["What actually flows in a torch?","A metal wire already contains mobile electrons. Connecting a source creates an electric field around the complete circuit; electrons drift while energy is transferred to the lamp. The battery does not send a fresh supply of electrons through an empty wire.","","carriers"],["Positive and negative charge","Electrons have negative charge; protons have positive charge. Like charges repel and unlike charges attract. A neutral object contains equal total positive and negative charge, rather than containing no charges.","",""],["Charging means transferring electrons","In ordinary rubbing or contact, electrons can transfer between materials. An object gaining electrons becomes negative; one losing electrons becomes positive. The positively charged object has not usually gained moving protons.","",""],["Charge is conserved","Charge may move between objects but the total charge of an isolated system is unchanged. If one object gains −4 nC, the other gains +4 nC. Signs track the imbalance, not a negative amount of matter.","",""],["Elementary charge is a tiny unit","One electron has charge −1.60 × 10⁻¹⁹ C. Coulomb values in circuits represent enormous numbers of carriers. For electron count use the magnitude of charge; use the negative sign only when asking for net electron charge.","N = |Q|/e; e = 1.60 × 10⁻¹⁹ C",""],["Current is a rate at a cross-section","Imagine a counting gate across one wire. Current says how much charge passes that gate each second. A current of 2 A means 2 C per second, not two electrons and not 2 C stored inside the lamp.","I = Q/Δt; 1 A = 1 C/s",""],["Conventional current has a defined direction","Conventional current follows the direction positive charge would move. In the external circuit it goes from the source positive terminal to negative terminal. Electron drift in a metal is opposite to that direction.","","loop"],["Carriers depend on the material","Metal current is carried by mobile electrons. In an electrolyte, positive and negative ions can both contribute: opposite charge signs moving opposite ways contribute conventional current in the same direction.","",""],["Current does not get used up","A lamp transforms energy, not charge. In a steady single loop, equal charge passes every cross-section per second. Otherwise charge would keep accumulating at some point, contrary to the steady-state condition.","",""],["A complete conducting route is needed","An open switch breaks the route. In the ideal steady-state model no current passes the gap, although a potential difference can exist across it. A short circuit provides an unintended low-resistance route.","","open"],["At a junction charge flow divides","For steady flow, current arriving at a node equals total current leaving. The split depends on the branches, not automatically on equal sharing. A 3 A arrival can split into 1 A and 2 A.","ΣIin = ΣIout","junction"],["Ammeter placement matters","An ideal ammeter has negligible resistance and is placed in series with the branch whose current is measured. Placing it across a source can create a dangerous low-resistance short. Use labelled schematic theory, not mains experiments.","","meters"],["Convert prefixes before calculating","Milli means 10⁻³ and micro means 10⁻⁶. Thus 250 mA = 0.250 A and 80 μC = 8.0 × 10⁻⁵ C. Convert minutes into seconds when current is in amperes.","2.5 min = 150 s",""],["Average and changing current","Q = IΔt assumes constant current or uses the average current over the interval. For a changing current, the area under a current-time graph gives charge. Split piecewise graphs into rectangles or triangles.","","pulse"],["A negative calculated current","A chosen arrow is a reference direction. A result I = −0.40 A means actual conventional current is 0.40 A opposite that arrow. Do not discard the sign without explaining the direction.","",""],["Microscopic drift versus rapid response","Electrons drift slowly on average and also have random motion. Circuit response is transmitted by the electric field; it is not necessary for one electron to travel from battery to lamp before the lamp responds.","",""]],"examples":[{"title":"Charge through a phone lead","q":"A constant 0.750 A flows for 4.00 min. Find the charge passing a cross-section and the number of electrons.","plan":"Current and duration are known, so find charge using Q = IΔt; then divide its magnitude by elementary charge.","work":[["Convert time","4.00 × 60 = 240 s; seconds are required because an ampere is coulombs per second."],["Find transported charge","Q = 0.750 × 240 = 180 C."],["Count electron carriers","N = 180/(1.60 × 10⁻¹⁹) = 1.125 × 10²¹ ≈ 1.13 × 10²¹ electrons."]],"check":"The result counts passage events across the section. It does not mean the lead stores 180 C. Electron drift is opposite conventional current.","fig":"carriers"},{"title":"A branching circuit","q":"A junction receives 1.80 A. One outgoing branch carries 650 mA. Find the other outgoing current.","plan":"Draw incoming and outgoing arrows; apply charge conservation rather than subtracting arbitrary magnitudes.","work":[["Convert the branch value","650 mA = 0.650 A."],["Write the node balance","1.80 = 0.650 + I₂."],["Solve and interpret","I₂ = 1.15 A in the assumed outgoing direction."]],"check":"0.650 + 1.15 = 1.80 A restores the incoming total. If the result were negative, the assumed outgoing arrow would reverse.","fig":"junction"}],"guided":[{"title":"Guided charge passage","q":"0.200 A flows for 15.0 s. Find charge.","value":3,"unit":"C","why":"Use Q = IΔt = 0.200 × 15.0 = 3.00 C.","tol":0.025},{"title":"Guided current","q":"24.0 C passes in 2.00 min. Find average current.","value":0.2,"unit":"A","why":"Convert 2.00 min to 120 s; I = 24.0/120 = 0.200 A.","tol":0.025},{"title":"Guided missing branch","q":"2.40 A enters; 0.90 A and 0.55 A leave. Find the third outgoing current.","value":0.95,"unit":"A","why":"I₃ = 2.40 − 0.90 − 0.55 = 0.95 A.","tol":0.025},{"title":"Guided electron count","q":"Express the number of electrons carrying 0.800 C as N × 10¹⁸. Enter N.","value":5,"unit":"×10¹⁸ electrons","why":"0.800/(1.60 × 10⁻¹⁹) = 5.00 × 10¹⁸ electrons.","tol":0.025}],"practice":[{"q":"A 320 mA current flows for 3.00 min. Calculate charge passage and electron count.","points":["320 mA = 0.320 A; 3.00 min = 180 s.","Q = IΔt.","Q = 57.6 C.","N = Q/e = 57.6/(1.60 × 10⁻¹⁹).","N = 3.60 × 10²⁰ electrons."]},{"q":"A node receives 2.50 A and 0.40 A through two wires. One wire carries 1.10 A out. Find current and direction in a fourth wire.","points":["Total incoming = 2.90 A.","Charge conservation: incoming = outgoing.","2.90 = 1.10 + I.","I = 1.80 A outgoing."]}],"tasks":[{"q":"A 0.450 A lamp operates for 80.0 s. Find transported charge and explain whether charge is consumed.","points":["Q = IΔt.","Q = 36.0 C.","Charge is conserved, not consumed.","The lamp transfers electrical energy to other forms."]},{"q":"A junction receives 900 mA; an outgoing branch carries 0.35 A. Calculate the other outgoing current and sketch the arrows.","points":["900 mA = 0.900 A.","Incoming arrow and two outgoing arrows at one node.","0.900 = 0.350 + I.","I = 0.550 A outward."]}],"bank":[{"q":"A current of 1 A means…","o":["1 C passes per second","1 electron passes per second","1 J passes per second"],"a":0,"explain":"Ampere measures coulombs per second."},{"q":"Electron drift in a metal is…","o":["along conventional current","opposite conventional current","perpendicular to the wire"],"a":1,"explain":"Negative carriers move opposite the positive-charge convention."},{"q":"A lamp in a steady series circuit uses up…","o":["charge","electrons","electrical energy"],"a":2,"explain":"Charge continues around the circuit while energy is transformed."},{"q":"At a steady node, 3 A enters and 1 A leaves one branch. Another branch carries…","o":["4 A out","2 A out","2 A in"],"a":1,"explain":"The outgoing total must equal 3 A."},{"q":"An ammeter is connected…","o":["in series with the measured branch","across the source","in parallel with any wire"],"a":0,"explain":"A low-resistance ammeter measures charge flow through itself."},{"q":"Charge from a current-time graph is…","o":["the slope","the signed area","the maximum current only"],"a":1,"explain":"Current multiplied by time has units of coulombs."}],"reference":"I = Q/Δt; Q = IΔt; N = |Q|/e. Convert time to seconds. Balance signed currents at each junction. State conventional current and electron drift separately.","extension":""},{"id":"y11-charge-current-voltage-focus-2","parent":"y11-charge-current-voltage","title":"Voltage: energy per charge and meter readings","shortTitle":"Voltage and energy","subtitle":"Connect two-point voltage measurements to energy transfers around a complete circuit.","concepts":[["Why a lamp needs two connections","Voltage is a difference between two points. Saying one point has 6 V is incomplete unless a reference is supplied. A lamp needs a potential difference across its terminals and a conducting route.","","meters"],["Energy is not the same as charge","Charge is a property of carriers. Energy is transferred to or from those carriers and the electromagnetic field. A large transported charge does not automatically mean a large energy transfer: voltage also matters.","",""],["Define potential difference","A potential difference of 1 volt means 1 joule of energy transferred per coulomb. Voltage describes energy per charge, not speed of electrons or total number of electrons.","V = W/Q; 1 V = 1 J/C",""],["Source versus load","A source converts chemical or another stored energy into electrical energy. A resistor, motor or lamp transfers electrical energy into thermal, mechanical or light energy. Both can have voltage across them.","",""],["Charge separation requires work","A source does work to maintain charge separation. It maintains a potential difference; it does not create charge from nothing. When connected, the circuit provides a route for charge flow and energy transfer.","",""],["Read terminal polarity","For a chosen reference, the positive source terminal is at higher electric potential than the negative terminal. Conventional current through a passive resistor moves from higher to lower potential. Electron movement is opposite.","",""],["An ideal wire has no voltage drop","Negligible wire resistance means negligible energy transfer per coulomb along that wire. Points connected only by an ideal wire form one electrical node. Their drawn distance apart does not imply different potential.","",""],["A voltmeter connects across two points","An ideal voltmeter has extremely high resistance and draws negligible current. Its probes connect to the two component terminals. It is placed in parallel, while an ammeter is placed in series.","","meters"],["Reversing the probes reverses the sign","A digital meter displays potential at its red probe minus potential at its black probe. Exchanging them changes +6 V to −6 V without changing the circuit. A sign describes the chosen measurement direction.","",""],["Choose a zero-potential reference","If the negative source terminal is called 0 V and the source is 12 V, its positive terminal is +12 V. Other circuit node potentials can then be found by subtracting drops as you follow conventional current.","","nodes"],["A loop restores its energy balance","After a complete trip around a steady circuit, a charge returns to its starting point. Total source energy supplied per coulomb equals total energy transferred per coulomb to loads.","Σsource rises = Σload drops",""],["Voltage can exist with no current","An open switch can have a voltage across its gap even when I = 0. Voltage does not prove a continuous conducting route exists. A charged battery can have terminal voltage with nothing connected.","","open"],["Equal node pairs mean equal voltage","Two components joined across the same two nodes have the same voltage. They need not have the same current. This topological definition is more reliable than deciding from a drawing looking side-by-side.","","parallel"],["Energy can be shared unequally","In series, the same charge passes every load, but each can transfer a different energy per coulomb. The component voltage drops therefore need not be equal; for ohmic resistors they depend on resistance.","",""],["Use consistent joules and coulombs","A value stated as 2.4 kJ must become 2400 J. A charge of 600 mC becomes 0.600 C. Put both into SI units before applying V = W/Q, and include volts on the result.","",""],["Difference, rise and drop","Keep signs and magnitudes clear. A 4 V drop along conventional current means the potential decreases by 4 V. Energy-transfer questions often ask for a positive magnitude W = |VQ|, with direction explained separately.","",""]],"examples":[{"title":"Energy supplied by a battery","q":"A 9.00 V source supplies 12.0 C to a circuit. Find energy supplied and explain the meaning of 9 V.","plan":"Voltage is energy per charge, so multiply it by the transported charge.","work":[["Identify quantities","V = 9.00 J/C and Q = 12.0 C."],["Calculate energy","W = VQ = 9.00 × 12.0 = 108 J."],["Explain the voltage","Each coulomb receives 9.00 J from the source; 12 coulombs therefore receive 108 J."]],"check":"The units (J/C) × C reduce to J. Voltage remains 9.00 V even though the total energy depends on Q.","fig":"loop"},{"title":"Three node potentials","q":"A 12.0 V source has negative terminal N at 0 V. A first load drops 4.00 V from P to M. A second load connects M to N. Find potentials P and M, second-load voltage, and energy for 5.00 C.","plan":"Assign source potential first, then subtract the first drop and use the second node difference.","work":[["Source and midpoint","P = 12.0 V; M = 12.0 − 4.00 = 8.00 V."],["Second voltage","V₂ = M − N = 8.00 − 0 = 8.00 V."],["Second energy transfer","W₂ = V₂Q = 8.00 × 5.00 = 40.0 J."]],"check":"The two drops add to 12.0 V. Energy supplied is 60.0 J, split into 20.0 J and 40.0 J.","fig":"nodes"}],"guided":[{"title":"Energy check","q":"6.00 V acts across a load while 8.00 C passes. Find energy.","value":48,"unit":"J","why":"W = VQ = 6.00 × 8.00 = 48.0 J.","tol":0.025},{"title":"Voltage check","q":"A load transfers 240 J for 20.0 C. Find voltage.","value":12,"unit":"V","why":"V = W/Q = 240/20.0 = 12.0 V.","tol":0.025},{"title":"Missing loop drop","q":"A 15.0 V source supplies two series loads. One drops 6.00 V. Find the other drop.","value":9,"unit":"V","why":"Energy per charge balances: 15.0 − 6.00 = 9.00 V.","tol":0.025},{"title":"Prefix check","q":"A load transfers 1.20 kJ while 50.0 C passes. Find voltage.","value":24,"unit":"V","why":"Convert 1.20 kJ to 1200 J; V = 1200/50.0 = 24.0 V.","tol":0.025}],"practice":[{"q":"A component transfers 720 J when 60.0 C passes. Find its voltage and explain it in words.","points":["V = W/Q.","V = 720/60.0 = 12.0 V.","Each coulomb transfers 12.0 J."]},{"q":"A 10.0 V source powers two series loads with drops 3.00 V and V₂. Find V₂ and energy transferred in the second load for 4.00 C.","points":["Loop energy balance: 10.0 = 3.00 + V₂.","V₂ = 7.00 V.","W₂ = V₂Q.","W₂ = 28.0 J."]}],"tasks":[{"q":"A 5.00 V component transfers 175 J. Calculate charge passage.","points":["Q = W/V.","Q = 175/5.00.","Q = 35.0 C."]},{"q":"A source provides 18.0 V. Two series load drops are 5.00 V and 13.0 V. For 2.00 C find source energy and both load energies; check conservation.","points":["Source energy = 18.0 × 2.00 = 36.0 J.","First load = 10.0 J.","Second load = 26.0 J.","10.0 + 26.0 = 36.0 J, consistent with energy conservation."]}],"bank":[{"q":"Voltage is…","o":["charge per second","energy per charge","energy per second"],"a":1,"explain":"Voltage is energy transferred per unit charge: V = W/Q, measured in J/C."},{"q":"An ideal voltmeter has…","o":["very high resistance","zero resistance","the same resistance as each lamp"],"a":0,"explain":"High resistance minimises loading."},{"q":"Points joined only by ideal wire have…","o":["the same potential","zero current","the same charge count"],"a":0,"explain":"There is no voltage drop along an ideal wire."},{"q":"Across an open switch there can be…","o":["voltage but no steady current","current but never voltage","neither voltage nor current in every case"],"a":0,"explain":"A break can prevent current while separating different potentials."},{"q":"Two series voltage drops are 2 V and 7 V. A single source must provide…","o":["5 V","14 V","9 V"],"a":2,"explain":"The energy-per-charge drops total 9 V."},{"q":"Reverse meter probes and a +4 V reading becomes…","o":["−4 V","0 V","+8 V"],"a":0,"explain":"The measured potential difference changes sign."}],"reference":"Voltage compares two points: V = W/Q. Energy magnitude W = VQ. Same ideal node means same potential; complete-loop energy rises and drops balance.","extension":""},{"id":"y11-charge-current-voltage-focus-3","parent":"y11-charge-current-voltage","title":"Circuit measurements: current, voltage and changing signals","shortTitle":"Circuit measurement scenarios","subtitle":"Select meter connections and interpret charge, energy and current-time evidence.","concepts":[["Choose what you want to measure","A current question asks about charge flow through a branch. A voltage question asks about energy per charge between two points. Start by marking the branch or two terminals before placing a meter.","","meters"],["Ammeter breaks into the route","Insert an ideal ammeter in series: all branch charge must pass through it. Its small resistance makes its voltage drop negligible. It does not measure the current of an adjacent branch it does not occupy.","",""],["Voltmeter bridges two terminals","Connect an ideal voltmeter across the load terminals. It compares potentials and draws negligible current. A voltmeter inserted in series can nearly block the circuit because its resistance is high.","",""],["Meter location in a branching circuit","A main-wire ammeter reads total current. A branch ammeter reads only that branch. You cannot label both readings equal unless all other branch currents are zero.","","junction"],["Open and closed switches","In a single-source series loop, an open switch gives I = 0. A load voltage can then be zero while the source voltage appears across the gap. When closed, the ideal switch has zero voltage drop.","","open"],["A short bypasses a load","An ideal wire across a resistor joins its terminals into one node: V across that resistor becomes zero. Real sources and wires have finite resistance and overheating can occur; the zero-resistance result is only an ideal model.","",""],["Read a constant-current graph","The area of a rectangle under I versus t is Q = IΔt. The horizontal axis must be time and the vertical axis current. A horizontal line means constant current, not zero charge transfer.","",""],["Read a ramp-current graph","If current increases linearly from zero, its charge transfer is a triangular area. Use the average of initial and final current for that interval. This average is not the final value.","","pulse"],["Split a piecewise graph","Draw vertical boundaries where the rule changes. Calculate each rectangle, triangle or trapezium separately and add signed areas. This prevents using one average across unrelated intervals.","",""],["Negative graph area","A negative current indicates flow opposite a chosen reference arrow. Signed area gives net charge passage. Total amount passing either way uses the sum of absolute areas, split at sign changes.","",""],["Find average current from total charge","Average current is net charge divided by total elapsed time. It need not occur at the time midpoint for a complex graph and need not equal the maximum current.","Iavg = Qnet/Δt",""],["Connect energy to a current graph","If voltage across the load is constant, W = VQ and Q is the signed current area. For a passive unidirectional load use positive transfer magnitudes. A changing voltage requires accounting for power over time.","",""],["Power-time graph has a different area","Power in watts is joules per second, so power-time area gives energy, not charge. Axis units distinguish this from current-time area.","W = area under P(t)",""],["Check meter polarity","If the source positive terminal feeds the ammeter positive input, conventional current typically reads positive. A negative reading can simply mean reversed leads; the circuit model has not violated charge conservation.","",""],["Real meters perturb the circuit","Real ammeters have small nonzero resistance; real voltmeters have large finite resistance. Their loading can matter in high-resistance circuits. Ideal assumptions explain the calculation but are approximations.","",""],["Evidence should test conservation","Measure total and branch currents independently and compare Itotal with their sum. Within uncertainty, agreement supports charge conservation. Disagreement calls for checking connections, readings and instrument uncertainty, not immediately a new physical law.","",""]],"examples":[{"title":"Charge from a triangular pulse","q":"Current rises linearly from 0 to 0.600 A in 4.00 s, then falls linearly to 0 in 2.00 s. Find charge transfer and mean current over 6.00 s.","plan":"Divide at the peak and use two triangular areas.","work":[["First triangular area","Q₁ = ½ × 4.00 × 0.600 = 1.20 C."],["Second triangular area","Q₂ = ½ × 2.00 × 0.600 = 0.600 C; Q = 1.80 C."],["Mean current","Iavg = 1.80/6.00 = 0.300 A."]],"check":"The mean is less than the peak. For this triangular pulse it is half the peak despite unequal rise and fall durations.","fig":"pulse"},{"title":"A meter reading predicts energy","q":"A 12.0 V load carries 0.250 A steadily for 80.0 s. Find charge passage and energy transferred.","plan":"The ammeter provides current, the parallel voltmeter provides voltage. Use their readings for charge and energy.","work":[["Charge","Q = IΔt = 0.250 × 80.0 = 20.0 C."],["Energy","W = VQ = 12.0 × 20.0 = 240 J."],["Alternative check","P = VI = 3.00 W; W = PΔt = 3.00 × 80.0 = 240 J."]],"check":"Two methods agree because W = VQ and Q = IΔt combine into W = VIΔt.","fig":"meters"}],"guided":[{"title":"Rectangle area","q":"0.400 A flows for 5.00 s. Find charge.","value":2,"unit":"C","why":"Area = 0.400 × 5.00 = 2.00 C.","tol":0.025},{"title":"Triangle area","q":"A triangular current pulse has base 8.00 s and height 0.500 A. Find charge.","value":2,"unit":"C","why":"Area = ½ × 8.00 × 0.500 = 2.00 C.","tol":0.025},{"title":"Trapezium area","q":"Current increases linearly from 0.200 to 0.600 A in 10.0 s. Find charge.","value":4,"unit":"C","why":"Average current = (0.200 + 0.600)/2 = 0.400 A; Q = 4.00 C.","tol":0.025},{"title":"Energy from area","q":"A 9.00 V load receives a unidirectional current area of 3.00 C. Find energy.","value":27,"unit":"J","why":"W = VQ = 9.00 × 3.00 = 27.0 J.","tol":0.025}],"practice":[{"q":"Current is 0.300 A for 4.00 s, then declines linearly to zero over 2.00 s. Find charge and mean current.","points":["Rectangle: 0.300 × 4.00 = 1.20 C.","Triangle: ½ × 0.300 × 2.00 = 0.300 C.","Q = 1.50 C.","Iavg = 1.50/6.00 = 0.250 A."]},{"q":"Describe ideal meter connections to measure load current and voltage. If readings are 0.800 A and 5.00 V, find energy in 30.0 s.","points":["Ammeter in series with load.","Voltmeter in parallel across load.","P = VI = 4.00 W.","W = PΔt = 120 J."]}],"tasks":[{"q":"A triangular pulse lasts 12.0 s with peak 0.400 A. Find charge passage and mean current.","points":["Q = ½ × base × height.","Q = 2.40 C.","Iavg = Q/12.0.","Iavg = 0.200 A."]},{"q":"A source feeds two branches with 0.25 A and 0.45 A. State main-wire ammeter reading and explain why a voltmeter is not inserted in that main wire.","points":["Itotal = 0.25 + 0.45.","Main reading = 0.70 A.","A voltmeter measures a two-point potential difference.","Its high resistance in series would strongly reduce current."]}],"bank":[{"q":"Current-time area has units…","o":["C","V","W"],"a":0,"explain":"Current is charge per time, so multiplying amperes by seconds gives coulombs."},{"q":"Power-time area gives…","o":["current","energy","resistance"],"a":1,"explain":"Power is energy per time, so multiplying watts by seconds gives joules."},{"q":"A triangular pulse with peak I and duration T carries charge…","o":["IT","½IT","2IT"],"a":1,"explain":"The geometric triangle area is half base times height."},{"q":"A main-wire ammeter reads…","o":["only the largest branch current","the sum of branch currents","the average branch current"],"a":1,"explain":"Charge conservation gives the sum."},{"q":"An ideal voltmeter in series would…","o":["nearly block current","increase current without limit","measure all branch currents"],"a":0,"explain":"An ideal voltmeter has infinite resistance."},{"q":"A negative current reading can indicate…","o":["reversed reference direction","charge destruction","negative elapsed time"],"a":0,"explain":"The sign states current direction relative to the chosen convention."}],"reference":"Ammeter: series and low resistance. Voltmeter: parallel and high resistance. Current-time area gives charge; power-time area gives energy. State ideal-meter assumptions.","extension":""},{"id":"y11-resistance-energy-power-focus-1","parent":"y11-resistance-energy-power","title":"Resistance and characteristic graphs: ohmic or not?","shortTitle":"Resistance and graphs","subtitle":"Read the axis convention before interpreting resistance, and recognise temperature-dependent loads.","concepts":[["Same voltage, different currents","Two components across 6 V can draw different currents. Resistance describes the ratio of potential difference to current at an operating point. It is not a count of electrons inside the component.","","iv"],["Define resistance first","If a component has 8 V across it and carries 2 A, its resistance at that point is 4 Ω. The definition R = V/I remains usable for non-ohmic components at individual operating points.","R = V/I; 1 Ω = 1 V/A",""],["Ohmic means a proportional relationship","At constant physical conditions, an ohmic component has current proportional to voltage. Its resistance is constant and its characteristic passes through the origin. Temperature must be controlled.","",""],["Ohm law is not a universal constant-R rule","For a filament lamp, temperature and resistance change as voltage rises. Calculating V/I at one point does not establish that the same value applies at another voltage.","",""],["Read the graph axes","A V-on-vertical versus I-on-horizontal graph has resistance as its straight-line gradient. An I-on-vertical versus V-on-horizontal graph has conductance, the reciprocal of resistance, as gradient.","","iv"],["Use large differences on a straight graph","Choose two well-separated points on the best-fit line; use ΔV/ΔI rather than dividing one tiny reading. This reduces sensitivity to reading uncertainty. Include axis units.","",""],["An I–V graph gets flatter for a hotter lamp","As lamp voltage rises, current grows less than proportionally because the filament becomes hotter and its resistance rises. Thus an I(vertical)–V(horizontal) curve flattens; the opposite-axis V–I curve steepens.","","lampgraph"],["Resistance at a curved-graph point","Use V/I to find the operating-point resistance. The tangent gradient ΔV/ΔI on a curved V–I graph is a different quantity and is not generally equal to V/I.","",""],["Why metal resistance increases with temperature","In the simple metal model, increased lattice vibration causes more scattering of moving electrons. The source must supply more energy per charge to maintain the same current.","",""],["Diode curves depend on polarity","A diode passes significant current in its forward direction above its turn-on region and very little in reverse below breakdown. Its characteristic is not a straight line through the origin.","","diode"],["Do not extrapolate beyond given data","A component may heat, saturate or enter a different operating region. Read or interpolate within the supplied characteristic unless the question explicitly grants a constant-resistance model.","",""],["Rearrange for the requested quantity","Use I = V/R for current or V = IR for voltage. Write the symbolic relation before substitution so the physical meaning survives the arithmetic.","I = V/R; V = IR",""],["Current units can change the answer by 1000","12 V divided by 40 mA means 12/0.040, not 12/40. The resistance is 300 Ω. A quick magnitude check catches the prefix error.","",""],["Voltage and resistance changes interact","If V doubles while R stays fixed, I doubles. If both V and R double, I is unchanged. Ratio reasoning requires stating what is held constant.","",""],["An open circuit has no steady conducting route","A wire break is often modelled as infinite resistance, so current is zero. Do not use a finite resistor equation to conclude that voltage must also be zero across the break.","",""],["A short is a low-resistance path","A short can draw high current limited by the real source and leads. Ideal zero-resistance sources with zero-resistance loops are not physically realistic models. Reason about limits rather than literal infinite currents.","",""]],"examples":[{"title":"Resistance from a straight characteristic","q":"A straight V-versus-I best-fit line passes through (0.10 A, 2.0 V) and (0.50 A, 10.0 V). Find resistance and current at 6.0 V.","plan":"Voltage is the vertical axis, so gradient ΔV/ΔI gives resistance.","work":[["Use differences","ΔV = 10.0 − 2.0 = 8.0 V; ΔI = 0.50 − 0.10 = 0.40 A."],["Gradient","R = 8.0/0.40 = 20 Ω."],["Predict current","At the same conditions, I = 6.0/20 = 0.30 A."]],"check":"The line also passes the origin for an ohmic model. The resistance unit is V/A = Ω.","fig":"iv"},{"title":"A non-ohmic lamp","q":"A lamp carries 0.200 A at 2.00 V and 0.400 A at 8.00 V. Find resistance at both points and explain why one constant R is unsuitable.","plan":"Use V/I separately at each operating point and compare.","work":[["Low-voltage point","R₁ = 2.00/0.200 = 10.0 Ω."],["High-voltage point","R₂ = 8.00/0.400 = 20.0 Ω."],["Interpretation","The resistance doubles as the hotter filament scatters carriers more; current is not proportional to voltage."]],"check":"Voltage rose fourfold but current only doubled. A fixed 10 Ω prediction would give 0.800 A, inconsistent with the supplied data.","fig":"lampgraph"}],"guided":[{"title":"Resistance check","q":"9.00 V gives 30.0 mA. Find resistance.","value":300,"unit":"Ω","why":"Convert 30.0 mA to 0.0300 A; R = 9.00/0.0300 = 300 Ω.","tol":0.025},{"title":"Current check","q":"A 40.0 Ω resistor has 12.0 V across it. Find current.","value":0.3,"unit":"A","why":"I = V/R = 12.0/40.0 = 0.300 A.","tol":0.025},{"title":"I–V slope check","q":"An I-versus-V straight line has gradient 0.0500 A/V. Find resistance.","value":20,"unit":"Ω","why":"I/V = 1/R, so R = 1/0.0500 = 20.0 Ω.","tol":0.025},{"title":"Ratio check","q":"An ohmic component carries 0.400 A at 4.00 V. Find current at 10.0 V, unchanged temperature.","value":1,"unit":"A","why":"R = 4.00/0.400 = 10.0 Ω; I = 10.0/10.0 = 1.00 A.","tol":0.025}],"practice":[{"q":"A 6.00 V component carries 120 mA. Find resistance. Would this single reading prove it is ohmic?","points":["120 mA = 0.120 A.","R = V/I = 50.0 Ω.","One operating point does not establish proportionality.","Several voltage-current readings at controlled conditions are needed."]},{"q":"A V-versus-I line has points (0.20 A, 3.0 V) and (0.60 A, 9.0 V). Find R and predict current at 12 V for unchanged conditions.","points":["R = ΔV/ΔI.","R = 6.0/0.40 = 15 Ω.","At fixed branch voltage, I = V/R means lower resistance gives greater current.","I = 12/15 = 0.80 A."]}],"tasks":[{"q":"A resistor draws 25.0 mA at 5.00 V. Find R and voltage required for 40.0 mA at constant temperature.","points":["R = 5.00/0.0250.","R = 200 Ω.","V = IR = 0.0400 × 200.","V = 8.00 V."]},{"q":"A lamp carries 0.10 A at 1.0 V and 0.30 A at 9.0 V. Calculate both resistances and explain the characteristic.","points":["First resistance = 10 Ω.","Second resistance = 30 Ω.","Resistance increases with filament temperature.","Current is not proportional to voltage, so the component is non-ohmic."]}],"bank":[{"q":"R = V/I applies…","o":["only to metal wires","at an operating point even for non-ohmic components","only at zero voltage"],"a":1,"explain":"It defines operating-point resistance."},{"q":"A V(vertical)-I(horizontal) straight-line gradient is…","o":["R","1/R","power"],"a":0,"explain":"With voltage vertical and current horizontal, ΔV/ΔI gives resistance in ohms."},{"q":"An I(vertical)-V(horizontal) straight-line gradient is…","o":["R","1/R","charge"],"a":1,"explain":"With current vertical and voltage horizontal, ΔI/ΔV gives conductance, the reciprocal of resistance."},{"q":"A hotter filament generally has…","o":["greater resistance","lower resistance","unchanged resistance"],"a":0,"explain":"In the simple metal model increased lattice motion increases scattering."},{"q":"One V and I pair proves ohmic behaviour…","o":["always","never by itself","if voltage is 1 V"],"a":1,"explain":"Proportionality needs multiple controlled measurements."},{"q":"40 mA is…","o":["40 A","0.040 A","400 A"],"a":1,"explain":"Milli means one-thousandth."}],"reference":"R = V/I; V = IR only with the appropriate operating-point R. Straight V–I gradient is R; straight I–V gradient is 1/R. Control temperature before claiming ohmic behaviour.","extension":""},{"id":"y11-resistance-energy-power-focus-2","parent":"y11-resistance-energy-power","title":"Electrical power and energy: ratings, costs and efficiency","shortTitle":"Power and energy scenarios","subtitle":"Choose between VI, I²R and V²/R, then follow useful output and energy cost.","concepts":[["A powerful appliance transfers energy faster","Power tells you joules transferred each second. Energy tells you total joules over an interval. A low-power appliance left on long enough can use more energy than a high-power one used briefly.","",""],["Start from energy per time","Power is energy divided by elapsed time. Use watts with joules and seconds. A value in kilowatts uses thousands of joules each second.","P = W/Δt; 1 W = 1 J/s",""],["Combine the electrical definitions","Voltage is energy per charge and current is charge per time. Multiplying them gives energy per time: P = VI. Use the voltage across and current through the same component.","P = VI",""],["Use current and resistance when supplied","Substituting V = IR into P = VI gives P = I²R. Square the current, including its units and any prefix conversion. This predicts dissipation for a resistor at that operating point.","P = I²R",""],["Use voltage and resistance when supplied","Substituting I = V/R gives P = V²/R. The whole voltage value is squared. Use the actual voltage across the component, not automatically the source voltage.","P = V²/R",""],["Hold the correct variable fixed","For fixed current, larger R means more resistor power. For fixed voltage, larger R means less power. Those statements are consistent because they describe different constraints.","",""],["A rating is a condition, not a promise","A 12 V, 6 W lamp rating describes operation at its specified voltage. At another voltage its power can change; for a filament its resistance may change too. Use given operating data or an explicitly constant-R approximation.","",""],["Energy from steady power","For constant power, multiply by operating time. If power changes, split into intervals or use area under a power-time graph. A maximum power value alone does not determine total energy.","W = PΔt",""],["Kilowatt-hour is an energy unit","A kWh is the energy transferred by 1 kW over 1 hour. It is not a unit of power. Convert to joules using 1000 W × 3600 s.","1 kWh = 3.60 × 10⁶ J",""],["Cost uses tariff and energy","Multiply energy in kWh by a stated cost per kWh. A tariff is supplied data, not a universal constant. If asked only for usage cost, do not invent fixed connection charges.","",""],["Useful versus total output","A motor can transfer electrical energy into both useful mechanical energy and unwanted heating. Total energy is conserved. Efficiency compares the useful output with total input, using the same interval.","η = useful output/input",""],["Efficiency applies to power too","For steady operation, η = Puseful/Pin. If a motor is 80% efficient, 0.80 of the electrical input power becomes the specified useful mechanical output, not 80% of its current.","",""],["Find an unknown current from a rating","If power and voltage are known for that operating condition, I = P/V. Ratings may be idealised; distinguish calculated operating current from a protective-device threshold.","",""],["Series loads share input power","The source power equals the sum of load powers for ideal wires and source. Use each load voltage and the common current. Loads need not dissipate equal power if their resistances differ.","","series"],["Parallel loads have their own current","Across a fixed-voltage source, each branch has the same voltage but can have different current and power. Sum branch powers to find source output.","","parallel"],["A plausible magnitude check","A 2 kW heater for one hour uses 2 kWh, not 2000 kWh. A small LED typically has low power relative to a heater; results differing by 1000 often indicate an unconverted milliamp or kilowatt.","",""]],"examples":[{"title":"Power of a resistor","q":"A 24.0 Ω resistor has 12.0 V across it. Find current, power and energy in 5.00 min.","plan":"Voltage and resistance are known, so find I = V/R; then use VI or V²/R and convert time.","work":[["Current","I = 12.0/24.0 = 0.500 A."],["Power","P = VI = 12.0 × 0.500 = 6.00 W; V²/R gives the same result."],["Energy","5.00 min = 300 s; W = 6.00 × 300 = 1800 J."]],"check":"Current is a rate of charge; energy is accumulated over time. The two power methods agree.","fig":""},{"title":"Usage cost and useful energy","q":"A 1.50 kW heater operates for 2.00 h. A stated tariff is $0.30/kWh. If 90% of its input reaches the intended room, find usage cost and useful room energy.","plan":"Use kW and hours for billing; use an efficiency fraction for useful output.","work":[["Input energy","E = 1.50 × 2.00 = 3.00 kWh."],["Usage cost","3.00 × $0.30 = $0.90, excluding any fixed charges."],["Useful energy","0.90 × 3.00 = 2.70 kWh = 9.72 MJ."]],"check":"The remaining 0.30 kWh is transferred elsewhere, not destroyed. The tariff is part of this question.","fig":""}],"guided":[{"title":"VI check","q":"A 9.00 V device carries 0.200 A. Find power.","value":1.8,"unit":"W","why":"P = VI = 9.00 × 0.200 = 1.80 W.","tol":0.025},{"title":"I²R check","q":"A 10.0 Ω resistor carries 0.300 A. Find power.","value":0.9,"unit":"W","why":"P = I²R = 0.300² × 10.0 = 0.900 W.","tol":0.025},{"title":"Energy check","q":"A 0.800 kW device runs for 3.00 h. Find energy.","value":2.4,"unit":"kWh","why":"E = 0.800 × 3.00 = 2.40 kWh.","tol":0.025},{"title":"Efficiency check","q":"A motor takes 100 W and delivers 75.0 W useful output. Find efficiency.","value":75,"unit":"percent","why":"η = 75.0/100 = 0.750 = 75.0%.","tol":0.025}],"practice":[{"q":"A 20.0 Ω resistor carries 0.400 A for 60.0 s. Find voltage, power and energy.","points":["V = IR = 8.00 V.","P = I²R = 3.20 W.","W = PΔt.","W = 192 J."]},{"q":"A 0.600 kW appliance runs for 5.00 h at a supplied tariff of $0.25/kWh. Find energy in kWh and joules and usage cost.","points":["E = 3.00 kWh.","1 kWh = 3.60 × 10⁶ J.","E = 1.08 × 10⁷ J.","Cost = $0.75."]}],"tasks":[{"q":"A 6.00 V motor draws 2.00 A with 70.0% efficiency. Find electrical input and useful output power.","points":["Pin = VI.","Pin = 12.0 W.","Puseful = 0.700 × 12.0.","Puseful = 8.40 W."]},{"q":"A 1.20 kW appliance operates for 45.0 min. Find energy in kWh and joules.","points":["Time = 0.750 h.","Energy = 1.20 × 0.750 = 0.900 kWh.","Convert using 3.60 MJ per kWh.","Energy = 3.24 MJ."]}],"bank":[{"q":"A kWh measures…","o":["power","energy","voltage"],"a":1,"explain":"It is power multiplied by time."},{"q":"At fixed V, resistor power is…","o":["V²/R","I/R","VR²"],"a":0,"explain":"P = VI and I = V/R combine into V²/R."},{"q":"At fixed I, doubling R makes power…","o":["double","half","unchanged"],"a":0,"explain":"P = I²R when current is held constant."},{"q":"Efficiency compares…","o":["useful output with input","current with charge","voltage with resistance"],"a":0,"explain":"Use energy or power for the same process."},{"q":"2 kW for 0.5 h uses…","o":["4 kWh","1 kWh","1000 kWh"],"a":1,"explain":"Energy = 2 × 0.5 = 1 kWh."},{"q":"Source power with ideal wires equals…","o":["the largest load power","the sum of load powers","zero"],"a":1,"explain":"Energy conservation applies to the complete circuit."}],"reference":"P = VI = I²R = V²/R for the relevant operating point; E = Pt. 1 kWh = 3.60 MJ. Use stated tariff for cost and useful/input for efficiency.","extension":""},{"id":"y11-resistance-energy-power-focus-3","parent":"y11-resistance-energy-power","title":"Wire resistance and heating: geometry and operating limits","shortTitle":"Wire and heating applications","subtitle":"Apply core resistance and power ideas; explore resistivity as a labelled extension.","concepts":[["Wires are not always ideal","Long thin leads can have appreciable resistance. Their voltage drop reduces voltage available to the intended load, while their heating transfers part of source energy away from useful output.","","wire"],["Separate core and extension","Core Year 11 calculations use R = V/I, P = VI and circuit rules. The wire-geometry model R = ρL/A below is an extension: useful for explaining materials and cable losses, not an additional stated syllabus equation.","",""],["Length changes the number of obstacles","In the simple uniform-wire model, doubling length at fixed material, area and temperature doubles resistance. There are more scattering regions along the carrier path.","R ∝ L (extension)",""],["Area means cross-section, not surface","A larger cross-sectional area gives more parallel paths for carriers. Doubling area at fixed length and material halves resistance. The area is measured in square metres, not the outer surface area of the wire.","",""],["Introduce resistivity carefully","Resistivity ρ describes a material at a specified temperature. Resistance R describes a particular object. The same material can make wires with different resistances by changing length or cross-section.","R = ρL/A (extension)",""],["Radius and diameter are different","For a circular cross-section, A = πr² = πd²/4. A diameter value must be halved before using πr². Because area is squared, using d as r makes area four times too large.","A = π(d/2)²",""],["Convert squared prefixes correctly","1 mm = 10⁻³ m, so 1 mm² = 10⁻⁶ m². A wire area of 0.50 mm² means 5.0 × 10⁻⁷ m², not 5.0 × 10⁻⁴ m².","",""],["Check resistivity dimensions","ρ has unit Ω m: multiplying by length gives Ω m² and dividing by area gives Ω. Dimensional analysis distinguishes resistivity from resistance and helps catch a missing area conversion.","",""],["Two leads contribute","A source-to-load circuit usually has outgoing and return conductors. If each is 2 m, total resistive wire length is 4 m. Do not count only the outward journey unless resistance is already supplied for the pair.","","lead"],["Voltage drop is IR","A current I through lead resistance Rlead produces voltage drop I Rlead. Subtract the total lead drop from source voltage to find voltage across the load. This is an application of loop energy conservation.","",""],["Cable heating is I²R","At the same lead resistance, doubling current quadruples heating power. A low-voltage device requiring high current can therefore suffer substantial lead losses.","Plead = I²Rlead",""],["Parallel strands reduce resistance","Identical strands connected between the same endpoints act in parallel. Their combined effective resistance is R/N for N equal strands. Their total cross-section also becomes N times larger in the uniform model.","",""],["Temperature changes the model","The supplied resistivity normally assumes a stated temperature. A heating wire can change resistance as it warms; do not claim a room-temperature value remains exact for a hot filament.","",""],["Ratings constrain a design","A resistor power rating is the permitted dissipation under specified conditions. Calculate actual power, then compare with the given limit. Being below a rating in an ideal calculation does not replace professional electrical design.","",""],["Greater R does not always mean greater heating","At constant current P = I²R rises with R; at constant component voltage P = V²/R falls. Explain which variable a source or control system holds fixed before making a heating prediction.","",""],["Theory stays separate from real mains work","These calculations use idealised low-voltage schematic examples. Actual cable choice depends on standards, installation, temperature and protection. The lesson explains physics; it does not instruct students to modify mains wiring.","",""]],"examples":[{"title":"Resistance of a uniform wire — extension","q":"A material has ρ = 1.70 × 10⁻⁸ Ω m. A wire is 4.00 m long with area 0.500 mm². Find R and heating power at 2.00 A.","plan":"Convert cross-sectional area to m², apply the extension geometry equation, then use core I²R.","work":[["Area conversion","A = 0.500 × 10⁻⁶ = 5.00 × 10⁻⁷ m²."],["Wire resistance","R = ρL/A = (1.70 × 10⁻⁸ × 4.00)/(5.00 × 10⁻⁷) = 0.136 Ω."],["Heating power","P = 2.00² × 0.136 = 0.544 W."]],"check":"The units reduce to Ω. Doubling current to 4.00 A would produce four times this power if R remained fixed.","fig":"wire"},{"title":"Lead losses in a low-voltage supply","q":"A 12.0 V ideal source feeds a 5.00 Ω load through a lead pair whose combined resistance is 1.00 Ω. Find current, load voltage and lead heating.","plan":"The lead pair and load are series elements; use their total resistance before calculating individual drops.","work":[["Total and current","Rtotal = 5.00 + 1.00 = 6.00 Ω; I = 12.0/6.00 = 2.00 A."],["Load voltage","Vload = I Rload = 2.00 × 5.00 = 10.0 V."],["Lead loss","Vlead = 2.00 V; Plead = I²Rlead = 4.00 W."]],"check":"Load power is 20.0 W; source power 24.0 W equals 20.0 + 4.00 W.","fig":"lead"}],"guided":[{"title":"Lead drop","q":"A lead pair has R = 0.200 Ω and carries 3.00 A. Find voltage drop.","value":0.6,"unit":"V","why":"V = IR = 3.00 × 0.200 = 0.600 V.","tol":0.025},{"title":"Lead heating","q":"The same 0.200 Ω pair carries 3.00 A. Find power.","value":1.8,"unit":"W","why":"P = I²R = 3.00² × 0.200 = 1.80 W.","tol":0.025},{"title":"Length ratio — extension","q":"A wire has resistance 0.400 Ω. Double only its length. Find new resistance.","value":0.8,"unit":"Ω","why":"R ∝ L for unchanged material, area and temperature.","tol":0.025},{"title":"Power limit","q":"A 100 Ω resistor dissipates 0.250 W. Find current magnitude.","value":0.05,"unit":"A","why":"I = √(P/R) = √(0.250/100) = 0.0500 A.","tol":0.0005}],"practice":[{"q":"A 9.00 V source feeds a 4.00 Ω load and 0.500 Ω combined lead resistance in series. Find current, load voltage and lead power.","points":["Rtotal = 4.50 Ω.","I = 9.00/4.50 = 2.00 A.","Vload = 2.00 × 4.00 = 8.00 V.","Plead = 2.00² × 0.500 = 2.00 W."]},{"q":"Extension: a wire has ρ = 2.00 × 10⁻⁸ Ω m, L = 3.00 m and A = 0.300 mm². Find R; explain the effect of doubling its diameter.","points":["A = 3.00 × 10⁻⁷ m².","R = ρL/A = 0.200 Ω.","Doubling diameter multiplies cross-sectional area by four.","Resistance falls to 0.0500 Ω, unchanged temperature and length."]}],"tasks":[{"q":"A 0.400 Ω lead pair carries 2.50 A. Find drop and heating; predict heating if current doubles with fixed R.","points":["Voltage drop = IR = 1.00 V.","Heating = I²R = 2.50 W.","Doubling current multiplies heating by four.","New heating = 10.0 W."]},{"q":"A 200 Ω resistor is specified for at most 0.500 W. In an ideal calculation find maximum voltage and current at that limit.","points":["V = √(PR).","V = √100 = 10.0 V.","At fixed branch voltage, I = V/R means lower resistance gives greater current.","I = 0.0500 A; this is a mathematical rating limit, not installation advice."]}],"bank":[{"q":"At fixed I, lead heating depends on…","o":["I²R","V/R","IR²"],"a":0,"explain":"Resistor heating is P = I²R: square the current, then multiply by resistance."},{"q":"R = ρL/A is labelled here as…","o":["extension wire model","charge conservation","a power definition"],"a":0,"explain":"The syllabus core names resistance and circuit relationships rather than resistivity."},{"q":"1 mm² equals…","o":["10⁻³ m²","10⁻⁶ m²","10⁻⁹ m²"],"a":1,"explain":"Square the length conversion."},{"q":"Doubling diameter at fixed L and material makes R…","o":["half","one quarter","double"],"a":1,"explain":"Cross-sectional area is proportional to diameter squared, so doubling diameter gives four times the area and one quarter the resistance."},{"q":"Two 2 m leads imply resistive total length…","o":["2 m","4 m","1 m"],"a":1,"explain":"Include outgoing and return conductors."},{"q":"A higher R means greater heating…","o":["always","only with the specified constraints, such as fixed I","never"],"a":1,"explain":"At fixed V the dependence reverses."}],"reference":"Core: Vlead = IRlead; Plead = I²Rlead. Extension: R = ρL/A; A = πd²/4. Include both leads, squared unit conversions and the stated temperature.","extension":"Wire resistivity and geometry are an extension application; core circuit and power calculations remain assessable."},{"id":"y11-series-parallel-circuits-focus-1","parent":"y11-series-parallel-circuits","title":"Series circuits: shared current and divided voltage","shortTitle":"Series circuit scenarios","subtitle":"Trace one route, calculate every drop, and explain what changes when a load is added.","concepts":[["Recognise one unbranched route","Series components share a current because no junction gives charge another route. Their position on the drawing can change without altering that single-route connection. Trace the wires rather than relying on appearance.","","series"],["Charge cannot disappear between loads","In steady state, the same charge per second passes both loads. A first resistor transfers energy but does not use up current. A second resistor therefore carries the same current.","",""],["Voltage drops add","Each load transfers energy per coulomb. Their drops add to the source rise. With ideal wires there are no additional wire drops.","Vsource = V₁ + V₂ + …",""],["Derive total resistance","Because the same I flows, Vtotal = IR₁ + IR₂. Factoring I gives Vtotal = I(R₁ + R₂), so Rtotal is the sum. This is a consequence of current and energy conservation.","Rtotal = R₁ + R₂ + …",""],["Find total current first","When source voltage and all resistances are known, calculate total resistance then I = Vsource/Rtotal. Use that current for every series component; do not divide source voltage by each resistance separately.","",""],["Find individual drops second","For each ohmic resistor use Vᵢ = IRᵢ. Check that the drops sum to the source voltage. A result giving each load the full source voltage belongs to a parallel model, not a series loop.","",""],["Larger resistance gets larger voltage share","At the same series current V ∝ R. If one resistance is twice another, its voltage drop is twice as large. Equal voltage division requires equal resistances.","V₁/V₂ = R₁/R₂",""],["A passive divider shares a source voltage","For two resistors in series, V₂ = Vsource R₂/(R₁ + R₂). This can be derived using common current. Specify that V₂ is measured across R₂, not across the other resistor.","","divider"],["Potential at a junction needs a reference","Set source negative to 0 V. Subtract the first resistor drop from source positive potential to find the midpoint. The second drop then returns to 0 V.","","nodes"],["Adding a resistor at fixed source voltage","Adding positive series resistance increases Rtotal and decreases all-loop current. Existing resistor drops and powers therefore decrease, provided their resistance remains fixed.","",""],["Removing a resistor changes the whole loop","Replacing one resistor with an ideal wire lowers total resistance. The remaining loads carry greater current. Simply subtracting the removed resistor power from the old source power is incorrect.","",""],["An open load stops the entire route","If one series component breaks open, current becomes zero throughout the single loop. This is why a simple series string is vulnerable to one open connection.","","open"],["A shorted load has zero drop","A bypassing ideal wire joins the load terminals into one node. Its voltage becomes zero and other series loads may receive more voltage. Treat the bypassed load separately from an open circuit.","",""],["Series power shares follow resistance","For fixed common current Pᵢ = I²Rᵢ. The higher-R component dissipates more power in that loop. Its current is still the same, so greater brightness is not explained by more current through that component.","",""],["Meter models preserve the route","An ideal ammeter in the route adds negligible resistance. An ideal voltmeter across a load draws negligible current. Real meters can alter readings slightly, but ideal analysis neglects this.","","meters"],["Check all three totals","After calculating, verify common current, sum of drops and sum of powers. Those checks test topology, arithmetic and conservation independently; they are stronger than checking only units.","",""]],"examples":[{"title":"Unequal resistors in one loop","q":"A 12.0 V ideal source supplies 4.00 Ω and 8.00 Ω in series. Find current, both voltage drops and both powers.","plan":"One route means one current; calculate total resistance first.","work":[["Total and current","Rtotal = 4.00 + 8.00 = 12.0 Ω; I = 12.0/12.0 = 1.00 A."],["Voltage drops","V₁ = 1.00 × 4.00 = 4.00 V; V₂ = 1.00 × 8.00 = 8.00 V."],["Power","P₁ = 1.00² × 4.00 = 4.00 W; P₂ = 8.00 W."]],"check":"Drops sum to 12.0 V and powers sum to VI = 12.0 W. The larger resistor receives more voltage at the same current.","fig":"series"},{"title":"Adding a series resistor","q":"A 10.0 V source initially powers a 5.00 Ω resistor. A second 5.00 Ω resistor is added in series. Compare original and new current and first-resistor power.","plan":"Analyse the two circuit configurations independently; keep source voltage fixed.","work":[["Original","Iold = 10.0/5.00 = 2.00 A; Pold = 2.00² × 5.00 = 20.0 W."],["New current","Rtotal = 10.0 Ω; Inew = 10.0/10.0 = 1.00 A."],["New first-load power","Pnew = 1.00² × 5.00 = 5.00 W, one quarter of the original."]],"check":"Current halves, so that fixed resistor power falls by a factor of four. Total new source power is 10.0 W.","fig":"series"}],"guided":[{"title":"Total resistance","q":"Three series resistors are 2.00 Ω, 3.00 Ω and 5.00 Ω. Find total.","value":10,"unit":"Ω","why":"Series resistance adds: 2 + 3 + 5 = 10.0 Ω.","tol":0.025},{"title":"Common current","q":"The same total is supplied by 20.0 V. Find current.","value":2,"unit":"A","why":"I = V/Rtotal = 20.0/10.0 = 2.00 A.","tol":0.025},{"title":"Individual drop","q":"A 3.00 Ω series resistor carries 2.00 A. Find its drop.","value":6,"unit":"V","why":"V = IR = 2.00 × 3.00 = 6.00 V.","tol":0.025},{"title":"Unknown resistor","q":"A 9.00 V source carries 0.300 A through a 10.0 Ω resistor and an unknown series resistor. Find unknown R.","value":20,"unit":"Ω","why":"Rtotal = 9.00/0.300 = 30.0 Ω; unknown = 30.0 − 10.0 = 20.0 Ω.","tol":0.025}],"practice":[{"q":"A 15.0 V source supplies 5.00 Ω and 10.0 Ω in series. Find I, both drops and source power.","points":["Rtotal = 15.0 Ω.","I = 1.00 A.","Drops are 5.00 V and 10.0 V.","Psource = VI = 15.0 W."]},{"q":"A 6.00 V source feeds a 4.00 Ω resistor and unknown R in series at 0.500 A. Find R and its power.","points":["Rtotal = 6.00/0.500 = 12.0 Ω.","R = 12.0 − 4.00 = 8.00 Ω.","Resistor heating is P = I²R: square the current, then multiply by resistance.","P = 2.00 W."]}],"tasks":[{"q":"A 24.0 V source powers 6.00 Ω and 18.0 Ω series resistors. Find current and individual powers.","points":["Rtotal = 24.0 Ω.","I = 1.00 A.","P₁ = 6.00 W.","P₂ = 18.0 W; sum = 24.0 W."]},{"q":"Two equal fixed resistors are in series across a fixed ideal source. One is bypassed by ideal wire. Explain changes to current and remaining resistor power.","points":["Total resistance halves.","Current doubles.","Remaining resistor resistance stays fixed.","I²R therefore gives four times its previous power."]}],"bank":[{"q":"Series resistors share…","o":["current","voltage regardless of R","power regardless of R"],"a":0,"explain":"There is one unbranched charge route."},{"q":"Total series resistance is…","o":["the sum","less than the smallest","the product only"],"a":0,"explain":"For an unbranched loop, resistor drops add at the same current, so Rtotal = ΣR."},{"q":"Larger R in the same series loop has…","o":["greater voltage drop","less current","always less power"],"a":0,"explain":"V = IR with common I."},{"q":"Adding series R at fixed source V makes I…","o":["decrease","increase","unchanged"],"a":0,"explain":"Total resistance increases."},{"q":"An ideal open component in a single loop causes…","o":["zero loop current","double current","unchanged current elsewhere"],"a":0,"explain":"It breaks the only route."},{"q":"If series current halves, a fixed resistor power becomes…","o":["half","one quarter","double"],"a":1,"explain":"Power scales as I² at fixed R."}],"reference":"Series: one route, common I; Rtotal = ΣR; Vsource = ΣV. Start with total R, then calculate each voltage and power. Check the full energy budget.","extension":""},{"id":"y11-series-parallel-circuits-focus-2","parent":"y11-series-parallel-circuits","title":"Parallel circuits: shared voltage and divided current","shortTitle":"Parallel circuit scenarios","subtitle":"Identify common nodes, calculate each branch, and explain fixed-voltage circuit changes.","concepts":[["Parallel means the same two nodes","Components are parallel when both terminals connect to the same two electrical nodes. They share a voltage regardless of shape or position in a sketch. A wire crossing without a connection dot does not automatically form a junction.","","parallel"],["Current has alternate routes","At a branch point, charge flow splits according to branch conditions. At a later node the flows recombine. A component in one branch does not necessarily carry total source current.","",""],["Same voltage follows the node definition","Each branch spans the identical potential difference VA − VB. Thus every parallel load has the full voltage between those nodes, but that voltage may not be the entire source voltage in a compound circuit.","",""],["Calculate each current with its branch resistance","Use Iᵢ = Vbranch/Rᵢ. A lower resistance draws more current at fixed shared voltage. Do not split current equally unless branch resistances are equal.","",""],["Total current is the sum","At steady nodes, Itotal = I₁ + I₂ + …. Add branch currents, not branch resistances, to recover the source current.","Itotal = ΣIbranch",""],["Derive reciprocal resistance","Itotal = V/R₁ + V/R₂. Factoring the shared V and comparing with V/Rtotal gives the reciprocal rule.","1/Rtotal = 1/R₁ + 1/R₂ + …",""],["Take the final reciprocal","If 1/Rtotal = 0.25 Ω⁻¹, Rtotal is 4 Ω, not 0.25 Ω. The intermediate value is conductance. Its reciprocal restores resistance units.","",""],["Two-resistor shortcut","For exactly two resistors, Rparallel = R₁R₂/(R₁ + R₂). It is derived from the reciprocal rule. Do not apply a product-over-sum expression to three resistors without reduction.","Rp = R₁R₂/(R₁ + R₂)",""],["Equivalent resistance is below the smallest branch","Parallel connection adds conducting routes, so the total current at a given voltage exceeds each individual branch current. Therefore Rtotal is lower than every positive branch resistance.","",""],["Equal branches share equally","N identical R resistors in parallel have Rtotal = R/N. Each branch receives V/R, and the source supplies N times that branch current.","",""],["Adding a branch to an ideal fixed-voltage source","Existing branch voltages and currents stay unchanged, while total source current and total power increase. A real source can sag; this simple prediction explicitly assumes ideal fixed terminal voltage.","",""],["Opening one branch","An open branch carries no current. Other branches still have a route and retain their voltage for an ideal source. Total source current falls by the removed branch current.","",""],["A source short affects every branch","An ideal wire across the common nodes forces their voltage difference toward zero in a realistic source-limited circuit and draws excessive current. Do not treat an open branch and a shorted branch as equivalent.","",""],["Parallel power is V²/R","At common V, a smaller R dissipates more power. This is opposite the comparison for resistors in series at common I. State the connection and fixed variable before comparing heating or brightness.","",""],["Measure total or individual current deliberately","Put a main ammeter before the node for Itotal, or inside a branch for Ibranch. Put a voltmeter across the two common nodes for the shared voltage.","","meters"],["Check sums and inequalities","Validate branch-current sum, source-power sum and Rtotal smaller than the smallest branch. A correct-looking decimal can still violate one of these physical checks.","",""]],"examples":[{"title":"Unequal parallel loads","q":"A 12.0 V ideal source has 6.00 Ω and 12.0 Ω resistors across it. Find each current, total current, equivalent resistance and powers.","plan":"The common voltage is 12.0 V; solve branches first, then combine.","work":[["Branch currents","I₁ = 12.0/6.00 = 2.00 A; I₂ = 12.0/12.0 = 1.00 A."],["Total and equivalent","Itotal = 3.00 A; Rtotal = 12.0/3.00 = 4.00 Ω."],["Powers","P₁ = 24.0 W; P₂ = 12.0 W; total = 36.0 W."]],"check":"4.00 Ω is below 6.00 Ω; 36.0 W equals source VI. Unequal resistances do not share current equally.","fig":"parallel"},{"title":"A branch is added","q":"A 9.00 V ideal source initially powers one 18.0 Ω resistor. A second 18.0 Ω resistor is connected in parallel. Find old and new total current and each load power.","plan":"Keep the common voltage fixed and analyse branch and source quantities separately.","work":[["Original branch","I = 9.00/18.0 = 0.500 A; P = 4.50 W."],["Added identical branch","The new branch also carries 0.500 A and dissipates 4.50 W."],["Source total","New total current = 1.00 A; source power = 9.00 W; equivalent R = 9.00 Ω."]],"check":"The original load power stays 4.50 W. The source supplies more energy per second, not a greater voltage.","fig":"parallel"}],"guided":[{"title":"Branch current","q":"A 15.0 Ω branch spans 6.00 V. Find current.","value":0.4,"unit":"A","why":"I = 6.00/15.0 = 0.400 A.","tol":0.025},{"title":"Total current","q":"Parallel currents are 0.400 A and 0.600 A. Find total.","value":1,"unit":"A","why":"Itotal = 0.400 + 0.600 = 1.00 A.","tol":0.025},{"title":"Equivalent resistance","q":"10.0 Ω and 15.0 Ω are parallel. Find Rtotal.","value":6,"unit":"Ω","why":"Rtotal = 10.0 × 15.0/(10.0 + 15.0) = 6.00 Ω.","tol":0.025},{"title":"Missing branch resistance","q":"An 8.00 V source supplies 1.20 A total; one branch takes 0.400 A. Find the other branch R.","value":10,"unit":"Ω","why":"Other current = 0.800 A; R = 8.00/0.800 = 10.0 Ω.","tol":0.025}],"practice":[{"q":"A 10.0 V source supplies 5.00 Ω and 20.0 Ω in parallel. Find branch currents, total current and equivalent R.","points":["Branch currents = 2.00 A and 0.500 A.","Total current = 2.50 A.","Rtotal = V/Itotal.","Rtotal = 4.00 Ω."]},{"q":"Three 12.0 Ω resistors are in parallel across 6.00 V. Find equivalent R and source power.","points":["Rtotal = R/3 = 4.00 Ω.","Each branch current = 0.500 A.","Total current = 1.50 A.","Psource = VI = 9.00 W."]}],"tasks":[{"q":"A 24.0 V source feeds 12.0 Ω and 24.0 Ω in parallel. Find each power and source current.","points":["Currents = 2.00 A and 1.00 A.","P₁ = 48.0 W.","P₂ = 24.0 W.","Itotal = 3.00 A; total power = 72.0 W."]},{"q":"An ideal 6.00 V source powers parallel 3.00 Ω and 6.00 Ω loads. The 6.00 Ω branch opens. Compare total current before and after and the remaining load current.","points":["Initial branch currents = 2.00 A and 1.00 A.","Initial total = 3.00 A.","Final total = 2.00 A.","Remaining branch still carries 2.00 A at unchanged source voltage."]}],"bank":[{"q":"Parallel resistors have the same…","o":["current always","voltage between common nodes","resistance always"],"a":1,"explain":"Their terminals span identical node potentials."},{"q":"Parallel equivalent R is…","o":["below the smallest branch R","the sum","above the largest branch R"],"a":0,"explain":"Additional paths increase conductance."},{"q":"At fixed shared V, lower R takes…","o":["more current","less current","same current"],"a":0,"explain":"At fixed branch voltage, I = V/R means lower resistance gives greater current."},{"q":"If one branch opens under ideal fixed V, another branch current…","o":["stays the same","becomes zero","doubles always"],"a":0,"explain":"Its voltage and resistance are unchanged."},{"q":"1/Rtotal = 0.20 Ω⁻¹ gives Rtotal…","o":["0.20 Ω","5.0 Ω","20 Ω"],"a":1,"explain":"The supplied value is conductance, so take its reciprocal: 1/0.20 = 5.0 Ω."},{"q":"Adding a parallel branch under fixed ideal V makes total power…","o":["increase","decrease","unchanged"],"a":0,"explain":"The new branch consumes additional power."}],"reference":"Parallel: same node-pair voltage; currents add; reciprocal resistances add. Calculate branches, then totals. Existing branch predictions assume an ideal fixed-voltage source.","extension":""},{"id":"y11-series-parallel-circuits-focus-3","parent":"y11-series-parallel-circuits","title":"Compound circuits: reduction, reconstruction and faults","shortTitle":"Compound circuit scenarios","subtitle":"Reduce only valid groups, restore branch quantities, and compare open or bypassed loads.","concepts":[["A mixed circuit needs a map","Identify electrical nodes first. A resistor before a split is not parallel with either branch resistor. Mark the two branch endpoints, then recognise the series element outside them.","","compound"],["Series requires no intervening branch","Two resistors are series only if their shared node has no alternative current route. Components next to each other on the page may not be series if a third wire leaves between them.","",""],["Parallel requires both endpoints in common","Sharing one endpoint is insufficient. Trace each component to both nodes before applying the reciprocal rule. Misidentifying a group leads to wrong voltage and current throughout the calculation.","",""],["Replace a valid group by an equivalent","The equivalent preserves the group voltage-current relationship at its two terminals. It does not say each physical resistor has the equivalent resistance or the group current.","",""],["Reduce from the inside outward","For one series resistor followed by two parallel branches, reduce the branches first. Then add their equivalent resistance to the series resistance. Sketch the simpler circuit at each step.","","reduced"],["Find source current using total R","Once fully reduced, Itotal = Vsource/Rtotal. This is the current through any element in series with the complete parallel group. It is not automatically each branch current.","",""],["Find group voltage before branch currents","The series element drop is ItotalRseries. Subtract from source voltage to find the voltage across the parallel group. Use that group voltage for each branch.","",""],["Restore the branch currents","Inside a parallel group, I₁ = Vgroup/R₁ and I₂ = Vgroup/R₂. Add them and check they equal group current. Reconstruction reverses reduction but respects each local rule.","",""],["Find component powers locally","For each component use its own voltage and current. A branch resistor power calculated with total current overestimates it. Source power must equal the sum for ideal wires and source.","",""],["An open branch changes total R","Remove the nonconducting branch, recalculate the remaining equivalent and then the entire circuit. Unlike pure parallel at the source, the group voltage can change because the series drop changes.","",""],["A bypassed group changes node potentials","An ideal wire across a whole group makes its voltage zero. Source current then depends on the remaining series elements and realistic source limits. Bypassed resistor current is zero when its voltage is zero.","",""],["A branch switch changes more than its own current","Closing an extra branch lowers group resistance and changes total current. With an upstream series resistor, the shared branch voltage decreases; an existing branch current can therefore decrease.","",""],["Loaded dividers are compound circuits","A measuring load connected across a divider resistor forms a parallel pair with it. Their equivalent is smaller, so the output voltage changes. A real load is not automatically negligible.","","loaded"],["Ideal voltmeters do not load a divider","An ideal infinite-resistance voltmeter takes zero current. It preserves the original divider ratio. A finite-resistance device must be included in the parallel group before calculating output.","",""],["Not every network can be reduced directly","A bridge network can have no simple series or parallel pair. Do not force the shortcuts onto it. More general node/loop methods are extension material unless the question supplies the needed structure.","",""],["Redraw topology without moving connections","You may bend wires and reposition symbols if the same nodes remain joined. You may not erase a junction or join crossing wires merely to make a familiar shape. Connectivity, not drawing geometry, defines the circuit.","",""]],"examples":[{"title":"Series before parallel","q":"A 12.0 V ideal source feeds a 2.00 Ω series resistor followed by parallel 6.00 Ω and 3.00 Ω branches. Find source current, group voltage and branch currents.","plan":"Reduce the parallel pair, then total; reconstruct individual values afterwards.","work":[["Reduce","Rp = 6.00 × 3.00/(6.00 + 3.00) = 2.00 Ω; Rtotal = 4.00 Ω."],["Source and group","Itotal = 12.0/4.00 = 3.00 A; series drop = 6.00 V; Vgroup = 6.00 V."],["Branches","I₆ = 6.00/6.00 = 1.00 A; I₃ = 6.00/3.00 = 2.00 A."]],"check":"Branch currents sum to 3.00 A. Powers 18.0 + 6.00 + 12.0 = 36.0 W equal source power.","fig":"compound"},{"title":"Opening a branch changes the other branch","q":"In the same 12.0 V circuit, the 3.00 Ω branch opens. Find the new source current and voltage across the remaining 6.00 Ω branch.","plan":"Remove only the open route and recalculate the full circuit: it is now 2.00 Ω and 6.00 Ω in series.","work":[["New total","Rtotal = 2.00 + 6.00 = 8.00 Ω."],["New current","I = 12.0/8.00 = 1.50 A, all through the remaining branch."],["New group voltage","V₆ = 1.50 × 6.00 = 9.00 V."]],"check":"Remaining branch current rose from 1.00 A to 1.50 A because its voltage rose. The fixed-voltage pure-parallel prediction does not apply to this group.","fig":"compound"}],"guided":[{"title":"Reduce branches","q":"4.00 Ω and 12.0 Ω are parallel. Find equivalent R.","value":3,"unit":"Ω","why":"Rp = 4 × 12/(4 + 12) = 3.00 Ω.","tol":0.025},{"title":"Include the series element","q":"Add a 2.00 Ω series resistor to that 3.00 Ω group. Find total.","value":5,"unit":"Ω","why":"Rtotal = 2.00 + 3.00 = 5.00 Ω.","tol":0.025},{"title":"Restore group voltage","q":"A 10.0 V source powers that circuit. Find the voltage across the 3.00 Ω equivalent.","value":6,"unit":"V","why":"Itotal = 10.0/5.00 = 2.00 A; Vgroup = 2.00 × 3.00 = 6.00 V.","tol":0.025},{"title":"Restore one branch","q":"The 12.0 Ω branch spans that 6.00 V group voltage. Find current.","value":0.5,"unit":"A","why":"I₁₂ = Vgroup/R = 6.00/12.0 = 0.500 A.","tol":0.025}],"practice":[{"q":"An 18.0 V source feeds 3.00 Ω in series with parallel 6.00 Ω and 12.0 Ω. Find total current, group voltage and branch currents.","points":["Rp = 4.00 Ω; Rtotal = 7.00 Ω.","Itotal = 18.0/7.00 = 2.57 A.","Vgroup = (18.0/7.00) × 4.00 = 10.3 V.","I₆ = 1.71 A; I₁₂ = 0.857 A; sum equals source current within rounding."]},{"q":"A 12.0 V divider uses upper 4.00 kΩ and lower 4.00 kΩ. A 4.00 kΩ load is placed across the lower resistor. Find loaded output voltage across the lower resistor.","points":["Lower resistor and load are parallel.","Their equivalent is 2.00 kΩ.","Total = 6.00 kΩ.","Vout = 12.0 × 2.00/6.00 = 4.00 V, rather than unloaded 6.00 V."]}],"tasks":[{"q":"A 10.0 V source feeds 1.00 Ω in series with parallel 4.00 Ω and 4.00 Ω. Find source current and branch powers.","points":["Rp = 2.00 Ω; Rtotal = 3.00 Ω.","Itotal = 10/3 = 3.33 A.","Group voltage = 20/3 = 6.67 V.","Each branch power = (20/3)²/4 = 11.1 W."]},{"q":"A 9.00 V source feeds 3.00 Ω in series with parallel 6.00 Ω and 6.00 Ω. One branch opens. Find source current before and after.","points":["Initial parallel equivalent = 3.00 Ω.","Initial total = 6.00 Ω; I = 1.50 A.","After opening, total = 3.00 + 6.00 = 9.00 Ω.","New source current = 1.00 A."]}],"bank":[{"q":"After reducing a parallel group, its equivalent current is…","o":["the sum of branch currents","every branch current","always zero"],"a":0,"explain":"The equivalent reproduces total terminal behaviour."},{"q":"To find branch current first determine…","o":["the voltage across that branch group","the source resistance only","the wire length only"],"a":0,"explain":"A series element can make group voltage differ from source voltage."},{"q":"A branch opening in a compound circuit…","o":["can change another branch voltage","never changes anything else","always shorts the source"],"a":0,"explain":"The total and series voltage division change."},{"q":"A real load across a divider resistor is…","o":["in parallel with that resistor","in series with both resistors","irrelevant always"],"a":0,"explain":"It joins the same two output nodes."},{"q":"A wire crossing has a junction…","o":["only if the schematic indicates connection","always","never"],"a":0,"explain":"Connectivity must be shown, typically by a dot."},{"q":"A nonreducible bridge should be…","o":["forced into parallel","treated with an appropriate general method","treated as one open wire"],"a":1,"explain":"Simple reduction is valid only for actual series/parallel groups."}],"reference":"Reduce valid groups → find source I → find local voltage → restore branch I → calculate individual powers. Reanalyse the whole circuit after a fault or load change.","extension":""},{"id":"y11-components-ac-safety-focus-1","parent":"y11-components-ac-safety","title":"Diodes, LEDs and sensors: characteristic-driven circuits","shortTitle":"Components and sensors","subtitle":"Apply non-ohmic core ideas; explore labelled sensor and divider applications.","concepts":[["Components need their own model","A fixed resistor, filament lamp and diode do not respond identically to voltage. Recognise the characteristic and operating conditions before using a constant-R prediction.","","diode"],["Forward and reverse describe diode polarity","The anode-to-cathode direction is forward conventional current. The cathode is marked by the bar in a circuit symbol. Reversing polarity suppresses normal current below breakdown; it does not reverse a large ordinary current.","",""],["A diode is non-ohmic","Its current is not proportional to voltage through all operating regions. A constant turn-on drop can approximate a forward conducting diode when explicitly supplied, but is not a universal exact rule.","",""],["An LED emits light when forward biased","An LED is a light-emitting diode. Its specified forward voltage depends on design and current. A source alone can drive excessive current, so a series current-limiting element is part of the model.","","led"],["Resistor voltage is not source voltage","For a conducting LED and series resistor, Vresistor = Vsource − VLED. Use this remaining voltage with the intended current to select resistance.","R = (Vsource − VLED)/I",""],["Check resistor dissipation","Once the resistor is chosen, calculate P = I²R or Vresistor I. A small current can still produce heating; compare with any supplied rating. This is an ideal low-voltage exercise, not a mains construction guide.","",""],["More than one LED shares source energy","For series LEDs, subtract the sum of forward drops from the source voltage before sizing the resistor. If the source is below that sum, the conducting-drop model may not apply.","",""],["Thermistors respond to temperature","For the NTC thermistor model used here, resistance decreases as temperature rises. PTC types behave differently, so state the type. Sensor behaviour is an application beyond the specifically named core examples.","","thermistor"],["An LDR responds to illumination","An LDR typically has lower resistance in brighter light. It is not a battery: it changes how an externally supplied circuit divides voltage or current. Treat values as supplied measured data.","",""],["A divider has a defined output","Two resistors connect in series between supply positive and 0 V. The junction voltage relative to 0 V is the voltage across the lower resistor. Reversing the sensor position reverses how this output changes.","","sensor"],["Sensor on the bottom","With a fixed upper resistor and NTC sensor below, warming lowers the lower resistance. Its share of the supply voltage falls, so the junction output relative to 0 V decreases.","",""],["Sensor on the top","With NTC sensor above and fixed resistor below, warming lowers total resistance and increases the fraction across the lower fixed resistor. The same junction output therefore increases.","",""],["Write the ratio before interpreting direction","Vout = Vsupply Rbottom/(Rtop + Rbottom) for an unloaded divider. Identify Rtop and Rbottom by their connection to supply and 0 V, not their names in the question.","Vout = Vs Rbottom/(Rtop + Rbottom)",""],["Loading can change the sensor output","A load across the output is parallel with the lower resistor. The effective lower resistance changes, so an unloaded-divider prediction can fail. Assume a high-input-resistance reader only when stated.","",""],["Interpolation is limited to given data","For nonlinear sensor resistance versus temperature data, interpolate only within the provided range if permitted. Do not assume a constant resistance change per degree beyond the graph.","",""],["Separate core from application","Ohmic/non-ohmic classification, resistance, series/parallel and power are core. Named sensor behaviour and divider design here are labelled applications; advanced transistor and control-system operation is not required for these calculations.","",""]],"examples":[{"title":"Current limiting for one LED","q":"A 5.00 V source powers an LED approximated by a 2.00 V forward drop. The desired current is 20.0 mA. Find the series resistor and its power.","plan":"The LED takes part of the source voltage; the resistor receives the rest.","work":[["Remaining voltage","VR = 5.00 − 2.00 = 3.00 V."],["Choose resistance","20.0 mA = 0.0200 A; R = 3.00/0.0200 = 150 Ω."],["Power","P = VR I = 3.00 × 0.0200 = 0.0600 W."]],"check":"Using 5.00/0.0200 would incorrectly assign all source voltage to the resistor. The specified diode-drop approximation is essential.","fig":"led"},{"title":"NTC sensor output — application","q":"An unloaded 6.00 V divider has a 2.00 kΩ upper fixed resistor and lower NTC sensor. Sensor resistance falls from 4.00 kΩ to 1.00 kΩ as it warms. Find junction output relative to 0 V in both states.","plan":"The output is across the lower sensor, so use its resistance in the numerator.","work":[["Cool state","Vout = 6.00 × 4.00/(2.00 + 4.00) = 4.00 V."],["Warm state","Vout = 6.00 × 1.00/(2.00 + 1.00) = 2.00 V."],["Explain direction","The lower sensor receives a smaller fraction of supply voltage as its resistance falls."]],"check":"All resistances may stay in kΩ because only their ratio is used. Moving the sensor to the upper position would reverse the output trend.","fig":"sensor"}],"guided":[{"title":"Resistor voltage","q":"A 9.00 V source powers an LED with 3.00 V drop. Find voltage left for the resistor.","value":6,"unit":"V","why":"Loop energy: VR = 9.00 − 3.00 = 6.00 V.","tol":0.025},{"title":"LED resistor","q":"That 6.00 V resistor drop must give 15.0 mA. Find R.","value":400,"unit":"Ω","why":"15.0 mA = 0.0150 A; R = 6.00/0.0150 = 400 Ω.","tol":0.025},{"title":"Divider output","q":"An unloaded 10.0 V divider has upper 3.00 kΩ and lower 2.00 kΩ. Find output relative to 0 V.","value":4,"unit":"V","why":"Vout = 10.0 × 2.00/(3.00 + 2.00) = 4.00 V.","tol":0.025},{"title":"Reversed sensor position","q":"Upper NTC is 1.00 kΩ and lower fixed resistor is 2.00 kΩ on 6.00 V. Find output.","value":4,"unit":"V","why":"Output is across the lower fixed resistor: 6.00 × 2.00/(1.00 + 2.00) = 4.00 V.","tol":0.025}],"practice":[{"q":"A 9.00 V source powers one LED with 3.00 V forward drop at 10.0 mA. Find required series R and its power under this model.","points":["Resistor voltage = 6.00 V.","I = 0.0100 A.","R = 600 Ω.","P = 6.00 × 0.0100 = 0.0600 W."]},{"q":"Application: a 12.0 V unloaded divider has upper 3.00 kΩ fixed resistor and lower LDR. The LDR changes from 9.00 kΩ in dim light to 1.00 kΩ in bright light. Find output relative to 0 V and explain the change.","points":["Dim output = 12.0 × 9/(3 + 9) = 9.00 V.","Bright output = 12.0 × 1/(3 + 1) = 3.00 V.","Bright light lowers LDR resistance.","The lower-resistor voltage share therefore decreases."]}],"tasks":[{"q":"A 6.00 V source powers an LED with 2.40 V forward drop and a 180 Ω series resistor. Calculate current and resistor power.","points":["Resistor drop = 6.00 − 2.40 = 3.60 V.","I = 3.60/180 = 0.0200 A.","P = VRI.","P = 0.0720 W."]},{"q":"Application: upper NTC falls from 6.00 kΩ to 2.00 kΩ. Lower fixed resistor is 2.00 kΩ; supply is 8.00 V. Calculate both junction outputs and state the reference.","points":["Output is junction relative to 0 V, across lower fixed resistor.","Initial = 8.00 × 2/(6 + 2) = 2.00 V.","Final = 8.00 × 2/(2 + 2) = 4.00 V.","Output rises as upper sensor resistance falls."]}],"bank":[{"q":"The diode cathode is shown by…","o":["the symbol bar","the source positive terminal","the largest resistor"],"a":0,"explain":"The cathode bar defines diode polarity."},{"q":"An LED series resistor receives…","o":["Vsource − VLED","all source V always","zero V always"],"a":0,"explain":"Drops add around the loop."},{"q":"An NTC sensor warms and its R…","o":["decreases","increases always","stays constant"],"a":0,"explain":"NTC means negative temperature coefficient."},{"q":"Divider output relative to 0 V across the lower resistor is…","o":["VsRbottom/(Rtop + Rbottom)","VsRtop/Rbottom","Vs always"],"a":0,"explain":"Use the lower resistor share."},{"q":"A lower LDR gets brighter and lower R; unloaded output…","o":["decreases","increases","is unchanged always"],"a":0,"explain":"Its fraction of the total falls."},{"q":"Named sensor/divider behaviour here is…","o":["a labelled application","an instruction to work on mains","a charge creation law"],"a":0,"explain":"It applies core circuit laws to additional component models."}],"reference":"LED: use supplied forward-drop model and a series current limiter. Divider output is junction-to-0 V across the lower element. Sensor position determines the trend.","extension":"Named sensors and voltage-divider design are extension applications of core non-ohmic and circuit ideas."},{"id":"y11-components-ac-safety-focus-2","parent":"y11-components-ac-safety","title":"Alternating current: direction, waveforms and effective values","shortTitle":"AC and effective values","subtitle":"Interpret changing current; use RMS calculations as a clearly labelled extension.","concepts":[["DC and AC describe direction over time","Steady DC keeps one current direction. AC reverses periodically. A current can vary in magnitude without being AC if it never reverses. Read the sign relative to a stated arrow.","","ac"],["A sine waveform crosses zero repeatedly","A sinusoidal voltage reaches positive and negative peaks and crosses zero between them. Its plotted line is voltage versus time, not a path travelled by a charge.","",""],["Period is one complete repeat","Measure from one positive peak to the next positive peak, not from a positive peak to the following negative peak. That latter separation is half a period.","",""],["Frequency counts complete cycles","Frequency f = 1/T. If T is in seconds, f is in hertz. A 20.0 ms period is 0.0200 s and corresponds to 50.0 Hz. This is waveform theory, not a mains experiment.","f = 1/T",""],["Peak and peak-to-peak are different","For a waveform centred on zero with peak magnitude Vp, the peak-to-peak span is 2Vp. A 10 V peak wave reaches +10 V and −10 V, giving a 20 V peak-to-peak span.","",""],["Signed average can be zero","A symmetric AC waveform has equal positive and negative voltage or current areas over a full cycle. Its signed mean is zero. That does not mean no energy is transferred to a resistor.","",""],["Resistor heating is positive in both halves","For a resistor i reverses with v. Instantaneous power p = vi = i²R is nonnegative: squaring either sign gives positive heating. Charge need not travel net one way to transfer energy.","",""],["RMS means root mean square — extension","RMS is an effective value based on heating equivalence. Square instantaneous values, average those squares, then take the square root. It is not the same as the signed average.","",""],["Sinusoidal effective voltage","For a zero-centred sine wave, Vrms = Vpeak/√2. This result depends on waveform shape. Do not apply it to square or irregular waves without justification.","Vrms = Vpeak/√2 (sinusoidal extension)",""],["Sinusoidal effective current","For a fixed pure resistor, Irms = Ipeak/√2 and Irms = Vrms/R. The voltage and current waveforms are in phase in this resistor-only model.","Irms = Ipeak/√2",""],["Average resistor power uses RMS","For a pure resistor Pavg = VrmsIrms = Vrms²/R = Irms²R. Peak voltage multiplied by peak current gives peak power, not average heating power.","Pavg = Vrms²/R (extension)",""],["An equal-level square wave differs","A symmetric square voltage of ±Vp has Vrms = Vp because its square is always Vp². This contrasts with the sine-wave factor and shows why waveform specification matters.","","square"],["Current still obeys conservation","At every instant the currents at a node balance. Direction changes do not suspend charge conservation. Choose consistent reference arrows for signed instantaneous quantities.","",""],["Rectification is a further application","A diode can block one polarity so a simple half-wave output has pulses of only one sign. It is not smooth steady DC; additional circuits are needed to reduce the variation. Treat this as an extension application.","",""],["Know what a stated voltage means","When a question specifies RMS, use it in average resistor-power equations. When it specifies peak, first convert for a sine wave. Never silently assume an unspecified graph amplitude is RMS.","",""],["Core versus extension boundaries","Core Year 11 circuit analysis uses current, voltage, resistance and power. Detailed AC/RMS relationships are not explicitly listed in the current syllabus; they are included here as labelled enrichment.","",""]],"examples":[{"title":"Period and effective voltage — extension","q":"A zero-centred sine voltage has positive peaks 0.0200 s apart and peak magnitude 12.0 V. Find frequency, RMS voltage and average power in 6.00 Ω.","plan":"Peak spacing gives full period; sine shape gives the √2 conversion.","work":[["Period and frequency","T = 0.0200 s; f = 1/T = 50.0 Hz."],["Effective voltage","Vrms = 12.0/√2 = 8.49 V."],["Average heating","Pavg = Vrms²/R = (12.0²/2)/6.00 = 12.0 W."]],"check":"Peak power is 24.0 W, twice the average for this pure-resistor sine-wave case.","fig":"ac"},{"title":"Same peak, different waveform — extension","q":"A 10.0 Ω resistor is supplied first by a zero-centred sine voltage with 10.0 V peak, then by a ±10.0 V square wave. Compare average heating powers.","plan":"Find RMS separately for each waveform before applying resistor power.","work":[["Sine","Vrms = 10.0/√2; Pavg = (100/2)/10.0 = 5.00 W."],["Square","Vrms = 10.0 V; Pavg = 100/10.0 = 10.0 W."],["Comparison","Square-wave heating is twice the sine heating at equal peak voltage."]],"check":"Both signed average voltages are zero. Their mean squared voltages differ, so their heating differs.","fig":"square"}],"guided":[{"title":"Period conversion","q":"A waveform period is 5.00 ms. Find frequency.","value":200,"unit":"Hz","why":"5.00 ms = 0.00500 s; f = 1/T = 200 Hz.","tol":0.025},{"title":"Sine RMS — extension","q":"A sine voltage has peak 14.142 V. Find RMS voltage.","value":10,"unit":"V","why":"Vrms = Vp/√2 ≈ 10.0 V.","tol":0.025},{"title":"Average heating — extension","q":"A pure 20.0 Ω resistor has 10.0 V RMS across it. Find average power.","value":5,"unit":"W","why":"Pavg = Vrms²/R = 100/20.0 = 5.00 W.","tol":0.025},{"title":"Peak-to-peak check","q":"A zero-centred voltage reaches ±6.00 V. Find peak-to-peak span.","value":12,"unit":"V","why":"Span = +6.00 − (−6.00) = 12.0 V.","tol":0.025}],"practice":[{"q":"Extension: a sine voltage has peak 20.0 V and period 10.0 ms. Find frequency, RMS voltage and average power in 25.0 Ω.","points":["T = 0.0100 s; f = 100 Hz.","Vrms = 20.0/√2 = 14.1 V.","Pavg = (20.0²/2)/25.0.","Pavg = 8.00 W."]},{"q":"Extension: a ±8.00 V square wave drives a 16.0 Ω resistor for 30.0 s. Find RMS voltage, average power and energy; explain why zero signed mean does not mean zero heating.","points":["Vrms = 8.00 V.","Pavg = 8.00²/16.0 = 4.00 W.","E = PΔt = 120 J.","Power depends on voltage squared, which is positive in both halves."]}],"tasks":[{"q":"Extension: a sinusoidal current has peak 0.600 A through a 50.0 Ω resistor. Find RMS current and average power.","points":["Irms = 0.600/√2 = 0.424 A.","Pavg = Irms²R.","Pavg = (0.600²/2) × 50.0.","Pavg = 9.00 W."]},{"q":"A waveform has positive peaks at 2.0 ms and 6.0 ms and voltage extrema ±5.0 V. Find period, frequency and peak-to-peak voltage.","points":["Period = 4.0 ms = 0.0040 s.","f = 250 Hz.","Peak magnitude = 5.0 V.","Peak-to-peak = 10.0 V."]}],"bank":[{"q":"AC necessarily…","o":["reverses current direction","has constant magnitude","has nonzero signed mean"],"a":0,"explain":"Direction reversal distinguishes AC."},{"q":"Positive to next positive peak measures…","o":["full period","half period","amplitude"],"a":0,"explain":"The waveform repeats after one full period."},{"q":"For a sine wave, Vrms is…","o":["Vp/√2","Vp/2","2Vp"],"a":0,"explain":"The shape-specific RMS result uses √2."},{"q":"A zero signed-mean AC can heat a resistor because…","o":["v² is positive in both halves","charge is created","resistance is negative"],"a":0,"explain":"Average heating depends on mean square, not signed mean."},{"q":"For a ±Vp square wave RMS equals…","o":["Vp","Vp/√2","zero"],"a":0,"explain":"Its squared magnitude is constant."},{"q":"VrmsIrms gives average power here when the load is…","o":["a pure resistor","any load without qualification","an open circuit with any current"],"a":0,"explain":"The simple product assumes resistor-only in-phase behaviour."}],"reference":"Waveform core interpretation: T, f = 1/T, sign and amplitude. Extension sine RMS: Vp/√2; pure resistor Pavg = Vrms²/R. State waveform and load assumptions.","extension":"Detailed AC and RMS calculations are enrichment beyond the explicitly listed Year 11 core circuit relationships."},{"id":"y11-components-ac-safety-focus-3","parent":"y11-components-ac-safety","title":"Electrical safety: faults, earthing and protection","shortTitle":"Safety and fault scenarios","subtitle":"Explain why different protections act on different faults using precise schematic models.","concepts":[["Electrical injury involves current through the body","Voltage can drive current through tissue, affecting heating and nerves. Risk depends on path, duration and body/contact resistance. No single simple resistance calculation can certify a situation safe.","",""],["Protection devices have different jobs","A fuse or circuit breaker responds primarily to excessive circuit current. An RCD responds to imbalance between outgoing and returning current. Earth wiring provides a fault path for exposed conductive parts.","","safety"],["Active, neutral and protective earth","Active and neutral form the normal supply and return route. Protective earth connects accessible metal cases to an earthing system in applicable equipment; it is not intended to carry normal load current.","",""],["Normal load current returns through neutral","With no leakage, the outgoing and returning current magnitudes match. The protective earth conductor carries negligible normal load current. This distinction helps interpret both fault diagrams and RCD sensing.","",""],["An active-to-case fault","Damaged insulation can connect an active conductor to an exposed metal case. Without effective protection the case can become dangerous to touch. The fault is a different route from the intended load.","","fault"],["Earthing gives a low-impedance fault route","A protective earth connection helps keep the case near earth potential and provides a path for fault current so appropriate protection can disconnect supply. It does not make every possible fault harmless.","",""],["Fuse operation","A fuse element melts when its current-time heating limit is exceeded, breaking the circuit. In a schematic single-pole supply, the protective interruption is on the active conductor so the downstream active supply is disconnected.","",""],["Circuit-breaker operation","A circuit breaker interrupts excessive current according to its designed characteristic and can usually be reset after fault correction. Its purpose is not to guarantee detection of every small hazardous body current.","",""],["Overload versus short circuit","An overload can come from too many loads sharing a supply. A short can be an unintended very low-resistance path. Both can produce high current and heating, but their causes differ.","",""],["RCD compares outgoing and returning currents","An RCD monitors active and neutral current balance. If some current takes another return route, the difference can trigger rapid disconnection at the device’s designed threshold and timing.","","rcd"],["Calculate the imbalance","Residual current magnitude is the difference between outgoing and returning currents. A load can have a normal overall current while a smaller portion leaks elsewhere.","Iresidual = |Iactive − Ineutral|",""],["RCD is not universal shock protection","A shock path from active to neutral can return equal monitored current and may not create residual imbalance. An RCD reduces particular risks; it does not remove the need for insulation and other protection.","",""],["Double insulation changes the case design","Class II equipment uses protective insulation arrangements separating accessible parts from hazardous live parts. It does not rely on a protective earth connection to an exposed metal case in the same way as earthed Class I equipment.","","insulation"],["Insulation and earth are not interchangeable","Insulation prevents unintended contact; protective earth provides a fault-current path if accessible conductive parts become live. A device may use one protection class or another; do not describe earth as ordinary insulation.","",""],["Heating explains overcurrent danger","For fixed lead resistance, P = I²R. Twice the current produces four times the heating. Circuit protection is coordinated with conductors and equipment; a greater protective rating is not automatically safer.","",""],["Use fault models for explanation only","All diagrams here are conceptual schematics. Do not test faults, touch conductors or modify mains equipment. Real safety work requires qualified personnel; our task is to explain protection and interpret supplied numerical data.","",""]],"examples":[{"title":"A residual-current fault","q":"A supplied conceptual circuit has 2.000 A outgoing active current and 1.970 A monitored neutral return. Calculate residual current. A stated RCD model trips at imbalance at least 30 mA; predict the model response.","plan":"Compare the two monitored currents, not the total load current with the threshold.","work":[["Difference","Iresidual = |2.000 − 1.970| = 0.030 A."],["Unit conversion","0.030 A = 30 mA."],["Model response","At the stated threshold, this model triggers disconnection; real devices also have specified response times and tolerances."]],"check":"The missing 30 mA returns by an unmonitored path. A 2 A load current alone is not what triggers the RCD.","fig":"rcd"},{"title":"Overload and lead heating","q":"Three supplied resistive loads of 300 W, 450 W and 600 W operate across an ideal 150 V schematic source. Find total current and heating in a 0.200 Ω lead pair.","plan":"Parallel loads receive the supply voltage. Sum powers to find total current, then use I²R for the leads.","work":[["Total load power","Ptotal = 300 + 450 + 600 = 1350 W."],["Load current","I = Ptotal/V = 1350/150 = 9.00 A."],["Idealised lead heating","Plead = I²R = 9.00² × 0.200 = 16.2 W."]],"check":"This simplified arithmetic uses fixed 150 V at the loads. It illustrates heating; it is not a prescription for a protective-device rating.","fig":"safety"}],"guided":[{"title":"Imbalance check","q":"Active is 1.200 A; neutral is 1.185 A. Find residual current.","value":15,"unit":"mA","why":"Difference = 0.015 A = 15 mA.","tol":0.025},{"title":"Load-current check","q":"A supplied theoretical resistive load has 240 W at 120 V. Find current.","value":2,"unit":"A","why":"I = P/V = 240/120 = 2.00 A.","tol":0.025},{"title":"Lead heating check","q":"A 0.300 Ω lead pair carries 4.00 A. Find power.","value":4.8,"unit":"W","why":"P = I²R = 4.00² × 0.300 = 4.80 W.","tol":0.025},{"title":"Heating ratio","q":"Current triples through a fixed-resistance lead. Enter the factor multiplying heating.","value":9,"unit":"times","why":"P ∝ I²: 3² = 9. This assumes resistance stays fixed.","tol":0.025}],"practice":[{"q":"A conceptual RCD monitors 3.000 A outgoing and 2.960 A returning. Find residual current. A stated model disconnects at 30 mA or more. Explain the predicted response and the different function of a fuse.","points":["Residual = 0.040 A = 40 mA.","40 mA exceeds the stated model threshold.","The RCD model disconnects due to imbalance.","A fuse responds to excessive current heating, rather than comparing active and neutral."]},{"q":"Explain a fault connecting active to an exposed metal case in appropriately earthed equipment. State the roles of earth conductor and overcurrent protection; identify one limitation of RCD protection.","points":["Case can become energised if insulation fails.","Earth provides a low-impedance fault route.","Sufficient fault current can operate coordinated protection and disconnect supply.","RCD detects monitored current imbalance, not every active-to-neutral shock path."]}],"tasks":[{"q":"A conceptual sensor reads 0.850 A outgoing and 0.825 A neutral return. Calculate imbalance in mA and explain what it represents.","points":["Difference = 0.025 A.","Residual current = 25 mA.","Some outgoing current is returning by another route.","Protection response requires the stated device threshold/timing, which is not supplied here."]},{"q":"Compare fuse, RCD and double insulation in three clear statements.","points":["Fuse interrupts excessive current through heating of its element.","RCD compares outgoing and returning monitored current and acts on residual imbalance.","Double insulation separates accessible parts from hazardous live parts through protective insulation arrangements.","They address different failure mechanisms; none is a reason to handle live wiring."]}],"bank":[{"q":"A fuse principally detects…","o":["overcurrent heating","active-neutral imbalance only","body temperature"],"a":0,"explain":"Its element melts under excess current-time heating."},{"q":"An RCD principally compares…","o":["active and neutral currents","wire lengths","load brightness"],"a":0,"explain":"Residual imbalance suggests another return route."},{"q":"Protective earth normally carries…","o":["the main load current","negligible load current","all neutral current"],"a":1,"explain":"It is a protective fault route, not the normal return."},{"q":"An active-neutral shock may evade RCD detection if…","o":["the monitored currents stay balanced","voltage is nonzero","earth is present"],"a":0,"explain":"No residual imbalance need be created."},{"q":"Double insulation relies on…","o":["protective insulation arrangements","using the case as neutral","increasing fuse size"],"a":0,"explain":"It separates accessible parts from hazardous live parts."},{"q":"Tripling current at fixed wire R multiplies heating by…","o":["3","6","9"],"a":2,"explain":"I²R gives the square of the current factor."}],"reference":"Fuse/breaker: excess current. RCD: monitored active-neutral imbalance. Protective earth: fault path for exposed conductive parts. Double insulation: protective separation. Explain mechanisms and limits, not live procedures.","extension":""}];
DATA.forEach(build);
})();
